// Bellmourn's words, more of them: what its people say to each other in the street. The same shapes
// as CHATS in ../townscripts.js: a line is [speaker, text], speaker 0 or 1 of the pair (or 2, for a
// conversation tagged 'trio', held by three); {a}, {b} and {c} are what speakers 0, 1 and 2 are called.
//
// Tags as in townscripts.js: 'any' (anyone), 'gossip' (any two grown-ups, now and then), or a calling
// (guard, worker, merchant, smith, baker, healer, hunter, gentry, traveller, old, young, farmer,
// innkeeper, learned, couple, velscour: Lord Velscour's garrison). A calling tag means speaker 0 holds
// that calling; 'couple' is only for husband and wife. Nobody here says the Flame's true name aloud.

export const MORE_CHATS = [
  // --------------- the catacombs: what the town says is under its feet
  { tags: ['any'], lines: [[0, 'They say the bell-ringers are buried right under the bell.'], [1, 'Fitting.'], [0, 'Standing up, with their hands raised.'], [1, 'Still waiting for a rope.']] },
  { tags: ['any'], lines: [[0, "There's a rope bridge down there, over a pit."], [1, 'Under the cathedral? Who strung it?'], [0, 'The old sexton, years ago.'], [1, "Rope doesn't last years."], [0, 'This rope is looked after.'], [1, 'By whom?'], [0, "That's the part nobody likes."]] },
  { tags: ['any'], lines: [[0, 'What is the Mourning Gulf, {b}?'], [1, 'A crack in the world, under the cathedral.'], [0, 'How deep?'], [1, "Drop a stone and start a prayer. You'll finish the prayer first."]] },
  { tags: ['any'], lines: [[0, 'My grandmother spoke of an abbot who burned.'], [1, 'At the stake?'], [0, 'At supper. At prayer. In his bed. He never stopped.'], [1, 'Cindermaw.'], [0, 'Not near the candles, {b}. They lean when you say it.']] },
  { tags: ['any'], lines: [[0, "The tower bell isn't the first bell, you know."], [1, 'What became of the first?'], [0, 'They buried it.'], [1, "You can't bury a bell."], [0, "You can if it won't stop ringing."]] },
  { tags: ['any'], lines: [[0, 'I felt a bell ring under my feet this morning.'], [1, 'Felt it?'], [0, 'In my teeth. Deep down. The tower never stirred.'], [1, "Don't tell Sister Odile. She'll want to go and look."]] },
  { tags: ['any'], lines: [[0, 'Where did they bury the poor, before the yard was dug?'], [1, 'Under the cathedral. In the floor of a long gallery.'], [0, 'With stones to mark them?'], [1, 'A few. Most just got the earth.'], [0, 'And the earth is giving them back.']] },
  { tags: ['any'], lines: [[0, 'The founders of Bellmourn lie under the cathedral.'], [1, 'In a great tomb, stepped like an altar.'], [0, 'Do they rest easy, do you think?'], [1, 'They built this town. Would you?']] },
  { tags: ['any'], lines: [[0, "What's an ossuary, {b}?"], [1, 'A room of bones, stacked neat.'], [0, 'Why neat?'], [1, 'So nobody argues over whose is whose.']] },
  { tags: ['any'], lines: [[0, 'They walled up the Plague Ossuary a hundred years back.'], [1, 'To keep the plague below?'], [0, 'That was the idea.'], [1, 'And?'], [0, "It's still below. Isn't it?"]] },
  { tags: ['any'], lines: [[0, 'The sexton built a ledge over the Gulf to keep watch.'], [1, 'Watch for what?'], [0, 'Things climbing. He watched till he died.'], [1, 'And then?'], [0, 'Then he watched a little longer.']] },
  { tags: ['any'], lines: [[0, "Sister Odile won't light the censers any more."], [1, 'Why not?'], [0, 'Something deep down swings one back. In time with hers.'], [1, "You've heard it?"], [0, 'Through the floor. Clink. Pause. Clink.']] },
  { tags: ['any'], lines: [[0, 'Why do the old folk knock twice on the cathedral door?'], [1, 'Habit.'], [0, "Grandmother said it's so they know."], [1, 'Who?'], [0, "The ones inside. That we're coming in. Not them coming out."]] },
  { tags: ['any'], lines: [[0, 'Were the founders buried with their money?'], [1, 'Every coin, they say.'], [0, "Then why hasn't anyone gone down for it?"], [1, 'Go and ask the founders, {a}.']] },
  { tags: ['any'], lines: [[0, 'The bell-ringers had a reliquary of their own, down there.'], [1, 'What would ringers keep as relics?'], [0, 'Their hands, they say.'], [1, "...I didn't need to know that."], [0, 'Neither did I. Now we both do.']] },
  { tags: ['any'], lines: [[0, 'Who keeps the lamps lit at the bottom of the cathedral stair?'], [1, 'The priest?'], [0, "She hasn't been down since the night she counted the dead."], [1, 'Then nobody does.'], [0, 'Then why are they lit?']] },
  { tags: ['any'], lines: [[0, 'I dropped a coin down the cathedral drain.'], [1, 'Let it go.'], [0, 'I heard it land.'], [1, "Good. Then it's gone."], [0, 'Then I heard it picked up.']] },
  { tags: ['any'], lines: [[0, "There's a door at the very bottom, they say. With bars."], [1, 'Against grave robbers?'], [0, 'It only opens when the old bell rings.'], [1, 'And who rings it?'], [0, "Whoever wants to meet what's behind the bars."]] },
  // ---------------------------------------- the graveyard and the dead
  { tags: ['any'], lines: [[0, 'The new graves are dug shallow these days.'], [1, 'Lazy sexton.'], [0, 'Kind sexton. They get out anyway. Why make it hard on them?']] },
  { tags: ['any'], lines: [[0, "I sat with my father's grave last night."], [1, 'In the dark? Alone?'], [0, 'Not alone. He sat up for a bit.'], [1, 'Saints. What did you do?'], [0, 'I told him about the harvest. He lay back down.']] },
  { tags: ['any'], lines: [[0, "Somebody's been tidying the graves."], [1, "That's nice."], [0, 'From underneath. The flowers are planted upside down.']] },
  { tags: ['any'], lines: [[0, 'Whose turn is it to put out the grave lanterns?'], [1, 'Mine, last week.'], [0, 'And this week?'], [1, "I'm not going. Last week one of them was already out. Holding it."]] },
  { tags: ['any'], lines: [[0, 'Why do they bury folk face down now?'], [1, 'Who does?'], [0, 'The sexton, the last few.'], [1, 'So they dig the wrong way.'], [0, 'Clever. Horrible. But clever.']] },
  { tags: ['any'], lines: [[0, 'I heard my name called from the graveyard.'], [1, 'Did you answer?'], [0, 'Of course not.'], [1, 'Good. Never answer.'], [0, 'It knew my middle name, {b}. Nobody knows my middle name.']] },
  { tags: ['any'], lines: [[0, "There's a fresh hole by the yew."], [1, 'A grave being dug?'], [0, 'A grave being left.']] },
  { tags: ['any'], lines: [[0, "Do you think the dead know they're dead?"], [1, 'Some of them.'], [0, 'Which ones?'], [1, 'The ones that look sorry about it.']] },
  // ------------------------------------- the roads and the wild places
  { tags: ['any'], lines: [[0, 'I took the Darkwood path to save time.'], [1, 'Did it?'], [0, 'I came out yesterday. Somehow.'], [1, "Well. That's a saving."]] },
  { tags: ['any'], lines: [[0, "The dread knights rode down to Millhaven's mill pond."], [1, 'To water their horses?'], [0, "Their horses don't drink. They stood and looked at it."], [1, 'At the water?'], [0, "At their own reflections. There weren't any."]] },
  { tags: ['any'], lines: [[0, "What's the Gloamhollow like inside?"], [1, 'Mushrooms that glow. Pretty, really.'], [0, "That's not so bad."], [1, "And ghasts that come on all fours to see who's admiring them."]] },
  { tags: ['any'], lines: [[0, 'Lights on the walls of Blackvigil last night.'], [1, 'You can see them from here?'], [0, 'From the hill. Red ones. They never once blinked.']] },
  { tags: ['any'], lines: [[0, 'Is it true the Vigil Road is paved with headstones?'], [1, 'Only the last mile.'], [0, 'Whose?'], [1, "Everyone's who complained about the first mile."]] },
  { tags: ['any'], lines: [[0, 'Brightwater Falls froze over in the night.'], [1, 'In autumn?'], [0, 'Only the middle. Shaped like a woman leaning out.'], [1, "I'm not fetching water from there any more."]] },
  { tags: ['any'], lines: [[0, 'My uncle went to the Trollhole after a dare.'], [1, 'And?'], [0, 'He came back with a tooth the size of my hand.'], [1, "The troll's?"], [0, "He wouldn't say. He has fewer teeth than he did."]] },
  { tags: ['any'], lines: [[0, 'Somebody nailed a sign at the edge of the Darkwood.'], [1, 'What does it say?'], [0, 'Turn back.'], [1, 'Sensible.'], [0, "It's facing the wrong way. It's for things coming out."]] },
  { tags: ['any'], lines: [[0, 'Do the Green Downs still smell of thyme?'], [1, 'Of thyme and horse and hot iron, now.'], [0, 'The dread knights?'], [1, 'They camp where the thyme was thickest. Out of spite, I think.']] },
  { tags: ['any'], lines: [[0, 'I saw a wagon on the Bellwood Trail with nobody driving it.'], [1, 'Runaway horse?'], [0, 'No horse. The wheels just went round.'], [1, 'Which way was it going?'], [0, 'Here.']] },
  // ------------------------------------- the green star and its crater
  { tags: ['any'], lines: [[0, 'The grass round the crater has come up green in a ring.'], [1, "It's autumn. Everything else is brown."], [0, "Green as midsummer. And the sheep won't touch it."]] },
  { tags: ['any'], lines: [[0, 'Folk go out to the crater at night to pray.'], [1, 'To what?'], [0, 'To the hole.'], [1, 'Does it answer?'], [0, "It hums. That's more than the cathedral does."]] },
  { tags: ['any'], lines: [[0, "I put a crater stone under my boy's pillow."], [1, "He was poorly, wasn't he?"], [0, 'He sleeps right through now.'], [1, 'And the stone?'], [0, "The stone doesn't sleep. It hums. Under his head. All night."]] },
  { tags: ['any'], lines: [[0, 'Rain stops at the edge of the crater, have you noticed?'], [1, "It can't."], [0, 'Stand at the rim in a shower. Dry on one side.'], [1, 'Which side?'], [0, 'The side that matters, I suppose.']] },
  { tags: ['any'], lines: [[0, 'I dreamt of green fire the night before it fell.'], [1, 'Everyone says that now.'], [0, 'I said it the morning before. To you. You told me to eat less cheese.'], [1, "...You did. I'm sorry. Eat what you like."]] },
  // ----------------- the stranger, and the one who went down the stair
  { tags: ['any'], lines: [[0, 'The stranger came up out of the cathedral grey to the eyebrows.'], [1, 'Dust?'], [0, 'Bone dust. They sneezed on the steps.'], [1, 'Bless them.'], [0, 'Bless whoever that was, too.']] },
  { tags: ['any'], lines: [[0, 'The stranger crossed the rope bridge, they say.'], [1, 'Over the Gulf?'], [0, 'And the dead came over behind.'], [1, 'And?'], [0, 'The bridge is a good deal lighter now.']] },
  { tags: ['any'], lines: [[0, 'Did the stranger ring the old bell down there, do you think?'], [1, 'How would you know if they had?'], [0, 'Every dog in Bellmourn howled at noon. All at once.'], [1, 'That was the stranger, then. Or noon.']] },
  { tags: ['any'], lines: [[0, 'The stranger bought rope from Grimwald.'], [1, 'How much?'], [0, 'All he had.'], [1, 'To climb down, or to tie something up?'], [0, "Grimwald didn't ask. He was busy counting."]] },
  { tags: ['any'], lines: [[0, 'Do you think the stranger sleeps?'], [1, 'Everyone sleeps.'], [0, "I've seen that lamp in the inn window at every hour."], [1, 'Maybe they sleep with it lit.'], [0, "After what's down there? I would too."]] },
  { tags: ['any'], lines: [[0, 'If the stranger goes into the Deep Undercroft...'], [1, "They won't."], [0, 'If they do. And put the burning abbot out.'], [1, "Then I'll light a candle for them."], [0, 'Not a candle. Anything but a candle.']] },
  { tags: ['any'], lines: [[0, "The stranger ate three bowls of Tobias's stew."], [1, 'Three? Nobody finishes one.'], [0, 'They asked for a fourth.'], [1, 'Then they really have been somewhere terrible.']] },
  { tags: ['any'], lines: [[0, 'I watched the stranger stand at the graveyard gate a long while.'], [1, 'Afraid?'], [0, 'Counting, I think. Like they were measuring the work.'], [1, "There's a lot of work in that yard."], [0, "They didn't look put off. They looked tired."]] },
  { tags: ['any'], lines: [[0, 'If the stranger dies down there, who gets their boots?'], [1, '{a}!'], [0, "It's a fair question. They're good boots."], [1, 'Ask again when they come back up.'], [0, "And if they don't?"], [1, "Then the boots will be down there with them. Won't they?"]] },
  { tags: ['any'], lines: [[0, 'Do you think the stranger can bring back the ones we lost?'], [1, 'From the crypts?'], [0, 'Just their names, even. Their rings.'], [1, 'Ask, {a}. The worst they can say is no.'], [0, 'The worst they can say is yes, and not come back.']] },
  { tags: ['any'], lines: [[0, 'The stranger walked in the dead of night past the graveyard.'], [1, 'Alone?'], [0, 'Not for long. The yard came up to meet them.'], [1, 'And?'], [0, 'It went back down again. In bits.']] },
  { tags: ['any'], lines: [[0, 'The stranger asked me the way to the Gloamhollow.'], [1, 'Which way did you send them?'], [0, 'The truth. North of the falls, up the cliff.'], [1, 'And the rest of the truth?'], [0, "That I'd pray. They thanked me for that part most."]] },
  // ---------------------------------------- hard times and soft hearts
  { tags: ['any'], lines: [[0, 'I still set a bowl out for my brother.'], [1, "It's been a year, {a}."], [0, 'The bowl is empty in the morning.'], [1, 'Then keep setting it.']] },
  { tags: ['any'], lines: [[0, "I'm frightened, {b}."], [1, 'Of what?'], [0, 'Of getting used to it.']] },
  { tags: ['any'], lines: [[0, 'Do you ever think of leaving the dead to the dead?'], [1, 'Every day.'], [0, 'And?'], [1, "They won't leave us to the living."]] },
  { tags: ['any'], lines: [[0, "My mother's ring came back to me."], [1, 'Came back? From where?'], [0, 'She was buried in it. It was on the doorstep, washed and shining.'], [1, 'Then she wanted you to have it.'], [0, 'Then why did she take my wedding ring in trade?']] },
  { tags: ['any'], lines: [[0, "I've forgotten my father's voice."], [1, "It's been a long time."], [0, 'I hear it at the graveyard gate sometimes.'], [1, "Then you haven't forgotten."], [0, "That's what frightens me."]] },
  { tags: ['any'], lines: [[0, "When this is over, I'm going to sleep for a week."], [1, "When what's over?"], [0, 'Bellmourn.'], [1, "Then you'll be sleeping in the yard, {a}."], [0, "Don't. I can hear them giggling at that."]] },
  { tags: ['any'], lines: [[0, 'Do you ever pray for the ones underground?'], [1, 'Every night.'], [0, 'Do you pray they rest, or pray they stay?'], [1, "Whichever they're listening for."]] },
  { tags: ['any'], lines: [[0, 'My little girl asked why the bell is sad.'], [1, 'What did you say?'], [0, 'That it misses someone.'], [1, 'Who?'], [0, 'She asked that too. I made porridge instead.']] },
  // ------------------------------------------------ everyday Bellmourn
  { tags: ['any'], lines: [[0, 'I tried to make soap.'], [1, 'And?'], [0, 'I made a sort of cheese.'], [1, 'Can you eat it?'], [0, 'You can wash with it. Just about.']] },
  { tags: ['any'], lines: [[0, "My cousin's visiting from Millhaven."], [1, 'Lovely.'], [0, "He's brought his sheep."], [1, 'How many?'], [0, "All of them. Into the house. He says the downs aren't safe."]] },
  { tags: ['any'], lines: [[0, 'I bought a new knife.'], [1, 'Sharp?'], [0, 'It cut the bread, the board and half the table.'], [1, 'Mind your fingers.'], [0, "I'm minding them very carefully."]] },
  { tags: ['any'], lines: [[0, 'I painted a saint on my door for luck.'], [1, 'Which saint?'], [0, "I don't know. He came out cross-eyed."], [1, 'Saint Squint, then. Patron of doorways.']] },
  { tags: ['any'], lines: [[0, 'Lend me your cloak, {b}?'], [1, "Where's yours?"], [0, 'Twelve feet up a tree in the Darkwood.'], [1, 'How?'], [0, "I left in a hurry. The tree didn't."]] },
  { tags: ['any'], lines: [[0, 'My sister says I snore like the Mourning Gulf.'], [1, 'Has she heard the Mourning Gulf?'], [0, "She says she doesn't need to now."]] },
  { tags: ['any'], lines: [[0, 'Keep your shutters closed tonight.'], [1, 'Full moon?'], [0, "Full moon, and the yard's restless."], [1, "It's always restless."], [0, "Tonight it's restless and bored. That's worse."]] },
  { tags: ['any'], lines: [[0, 'My neighbour borrowed my ladder.'], [1, 'And?'], [0, "He's been on my roof two days."], [1, 'Doing what?'], [0, "Watching the graveyard. He says it's safer up there."], [1, 'Is it?'], [0, "It's drier, anyway."]] },
  { tags: ['any'], lines: [[0, "Do you think it'll snow early this year?"], [1, 'Saints, I hope not.'], [0, "Why? Snow's pretty."], [1, 'Snow shows footprints. Then you know how many there were.']] },
  { tags: ['any'], lines: [[0, "I've decided to be cheerful today, {b}."], [1, 'Why?'], [0, 'No reason. Somebody in this town has to.'], [1, 'How long will it last?'], [0, 'Till the bell, I expect.']] },
  { tags: ['any'], lines: [[0, "There's a cart stuck in the mud by the square."], [1, 'Whose?'], [0, "Nobody's. It's been there since spring."], [1, "Then it's the square's cart now."], [0, 'The square can push it, then.']] },
  { tags: ['any'], lines: [[0, "I've started talking to my chickens."], [1, 'Do they listen?'], [0, 'Better than my sons do.'], [1, 'Do they answer?'], [0, "Don't be daft. Not in daylight."]] },
  { tags: ['any'], lines: [[0, 'Have you seen my spectacles?'], [1, 'On your head.'], [0, 'These are my other spectacles. The ones for far.'], [1, 'And what are you looking at far away?'], [0, 'The tree line. I like to know where it is.']] },
  { tags: ['any'], lines: [[0, 'How was the wedding at Millhaven?'], [1, 'Short.'], [0, 'Short and sweet?'], [1, "Short. The dread knights rode past. Everyone ran. They're married, I think."]] },
  { tags: ['any'], lines: [[0, "The wind's changed, {b}."], [1, 'From the west.'], [0, 'From Blackvigil.'], [1, "Wind doesn't come from a castle."], [0, 'Then why does it smell of polish and fear?']] },
  { tags: ['any'], lines: [[0, "Do you ever wonder what's beyond the Green Downs?"], [1, 'Hills. More hills.'], [0, 'And beyond those?'], [1, 'Some other town with its own bell, I hope. Not ours.']] },
  { tags: ['any'], lines: [[0, "What's the time, {b}?"], [1, 'Not yet the bell.'], [0, 'How long till the bell?'], [1, "It's always not yet. Until it's now."]] },
  { tags: ['any'], lines: [[0, 'Somebody left a basket of apples at my door.'], [1, 'Kind.'], [0, 'With a note. "For the trouble."'], [1, 'What trouble?'], [0, "That's the thing. I haven't had any. Yet."]] },
  { tags: ['any'], lines: [[0, "I've lost the key to my cellar."], [1, 'Break the lock.'], [0, "I'd rather not."], [1, 'Why?'], [0, "I locked it on purpose. Something's in there being quiet."]] },
  { tags: ['any'], lines: [[0, 'Morning, {b}. Sleep well?'], [1, 'Like the dead.'], [0, "Don't. Not in Bellmourn."], [1, 'Like a log, then.'], [0, 'Better. Logs stay put.']] },
  { tags: ['any'], lines: [[0, 'What do you want for your name day?'], [1, 'Quiet.'], [0, "That's hard to wrap."], [1, 'Then a pie. And quiet.']] },
  { tags: ['any'], lines: [[0, "There's a fiddle on the cathedral steps."], [1, 'Whose?'], [0, "Nobody's. It plays when you're not looking."], [1, 'Is it any good?'], [0, 'It knows one tune. A sad one. It does it very well.']] },
  { tags: ['any'], lines: [[0, 'The well water tastes of pennies today.'], [1, "Someone's been wishing."], [0, 'It tastes of old pennies, {b}. Pennies from before the reeve.']] },
  { tags: ['any'], lines: [[0, 'My boots are full of graveyard clay again.'], [1, 'You cut through the yard?'], [0, 'I never cut through the yard.'], [1, 'Then how...'], [0, "I'd like to know that myself."]] },
  { tags: ['any'], lines: [[0, 'Are you coming to the feast of Saint Ivo?'], [1, 'Is there to be one?'], [0, 'Every year. We eat bread and say nothing of his Barrow.'], [1, 'What happens if you mention it?'], [0, 'Nobody knows. Nobody has, since my grandmother.']] },
  { tags: ['any'], lines: [[0, 'I owe you a copper, I think.'], [1, 'Two.'], [0, 'One and a half. I bought half your pie.'], [1, 'You ate the whole pie.'], [0, 'I ate half. The other half I enjoyed.']] },
  { tags: ['any'], lines: [[0, 'Can you keep a secret?'], [1, 'In Bellmourn? Nobody can.'], [0, "Then I'll tell you, and you can be the first to fail."], [1, 'Go on.'], [0, "I like it here. Don't you dare tell anyone."]] },
  // -------------------------------- gossip: who's doing what with whom
  { tags: ['gossip'], lines: [[0, 'Hob bought two lengths of ribbon from Ebb.'], [1, 'For a girl?'], [0, "Ebb asked. He said for her hair, what's left of it."], [1, 'Oh, Hob. Not the mausoleum again.']] },
  { tags: ['gossip'], lines: [[0, 'Lady Isolde had the stranger to tea.'], [1, 'At the town hall?'], [0, 'Two hours. They talked of nothing but the crypts.'], [1, 'And she came out pale?'], [0, 'She came out pink. Make of that what you will.']] },
  { tags: ['gossip'], lines: [[0, "The reeve's hair is not his own."], [1, 'Never!'], [0, 'It blew off in the square. Wat chased it to the well.'], [1, 'Did he give it back?'], [0, "With a mouse in it. The reeve didn't notice till the sermon."]] },
  { tags: ['gossip'], lines: [[0, 'Agnes takes Garrow a hot loaf every morning.'], [1, "He's a smith. He has his own fire."], [0, 'He says hers is warmer.'], [1, 'Does he now.']] },
  { tags: ['gossip'], lines: [[0, 'Corin sold the same map of the Gloamhollow to three people.'], [1, 'The same map?'], [0, 'Each with the treasure marked somewhere else.'], [1, "Which one's right?"], [0, 'Whichever one comes back to complain.']] },
  { tags: ['gossip'], lines: [[0, 'Sigurd writes a letter north every week.'], [1, 'To whom?'], [0, 'A wife, Elsie thinks. He never sends them.'], [1, 'Why not?'], [0, 'He keeps them in his pack. A whole stack. He reads the old ones.']] },
  { tags: ['gossip'], lines: [[0, 'Joan has started wearing scent.'], [1, 'Over the tannery?'], [0, 'Over the tannery.'], [1, 'Is it winning?'], [0, "It's losing, but bravely."]] },
  { tags: ['gossip'], lines: [[0, 'Maud arm-wrestled one of the Sworn at the inn.'], [1, 'She never!'], [0, 'Ulf, the big one. He kept his helm on.'], [1, 'And who won?'], [0, 'She kept his gauntlet. Draw your own conclusions.']] },
  { tags: ['gossip'], lines: [[0, 'Widow Harrow has set a second pillow on her bed.'], [1, 'A lodger?'], [0, "She won't say. Her husband won't like it."], [1, 'Her husband suggested it, I heard.']] },
  { tags: ['gossip'], lines: [[0, 'Mother Hesk danced at the crater rim on holy night.'], [1, 'Hesk? With her knees?'], [0, 'Her knees were the best part. Everybody said so.']] },
  { tags: ['gossip'], lines: [[0, 'Wat wrote Elsie a poem.'], [1, 'Can Wat write?'], [0, 'No. He drew it.'], [1, 'What did he draw?'], [0, 'A heart, I think. Or a turnip. She kept it either way.']] },
  { tags: ['gossip'], lines: [[0, 'Hild beat the sergeant at dice.'], [1, 'How much?'], [0, "A week's pay."], [1, 'Did he pay?'], [0, "He put her on the graveyard watch for a week. They're even."]] },
  { tags: ['gossip'], lines: [[0, 'Idris lost his eyebrows again.'], [1, 'Third time this year.'], [0, 'He says they grow back cleverer each time.'], [1, 'Are they?'], [0, "The left one is. The right one's sulking."]] },
  { tags: ['gossip'], lines: [[0, "Tam's been sleeping in the barn with his cow."], [1, 'Why?'], [0, 'He says she has bad dreams.'], [1, 'Cows dream?'], [0, 'This one wakes up mooing at the crater.']] },
  { tags: ['gossip'], lines: [[0, 'Sister Odile went into the Tolling Bell last night.'], [1, 'Sister Odile? Drinking?'], [0, 'She read the Canticle to the drunks. They wept.'], [1, 'And then?'], [0, 'And then she bought a round. Nobody believes me.']] },
  { tags: ['gossip'], lines: [[0, "The reeve's been writing to Blackvigil."], [1, 'To Malgrave? Himself?'], [0, 'Asking very politely for a lower tithe. In his best hand.'], [1, 'Brave man.'], [0, 'Foolish man. They write with the same hand round here.']] },
  { tags: ['gossip'], lines: [[0, 'Bertha sleeps with the cash box.'], [1, 'Under the bed?'], [0, 'In it. Grimwald sleeps on the floor.'], [1, "Doesn't he mind?"], [0, 'He says the box has softer feet.']] },
  { tags: ['gossip'], lines: [[0, 'Dame Sabine was seen feeding a stray cat.'], [1, 'One of the Sworn, with a heart?'], [0, 'She named it Tithe.'], [1, 'Because?'], [0, 'Because it takes a tenth of everything on your plate.']] },
  { tags: ['gossip'], lines: [[0, "I don't think Bram can read."], [1, 'One of the Sworn?'], [0, 'He holds the notices upside down and frowns very hard at them.'], [1, "Don't you dare tell him."], [0, "I wouldn't. I'd like to keep my letters the right way up."]] },
  { tags: ['gossip'], lines: [[0, 'Magister Corvus bought every candle Ebb had.'], [1, 'Every one? What for?'], [0, "He wouldn't say. She charged him double."], [1, 'Good for her.'], [0, 'And lit one for the rest of us with the change.']] },
  { tags: ['gossip'], lines: [[0, 'Black Morwen smiled at someone yesterday.'], [1, 'Who?'], [0, "I don't know. They left town in the morning."], [1, 'Left on purpose?'], [0, "Left. Let's leave it there."]] },
  { tags: ['gossip'], lines: [[0, 'The stranger fell asleep at the bakehouse door.'], [1, 'And Agnes let them?'], [0, 'She put a sack over them and baked round them all night.'], [1, "That's Agnes. Feeds stray dogs too."]] },
  { tags: ['gossip'], lines: [[0, 'Someone saw the stranger kneel at a little grave in the yard.'], [1, 'Whose?'], [0, "A child's. Nobody knows why that one."], [1, "Maybe it's somebody they lost."], [0, 'Maybe it asked them for something.']] },
  { tags: ['gossip'], lines: [[0, 'Tobias is putting money by.'], [1, 'For what?'], [0, 'He won\'t say. A box in the cellar marked "after."'], [1, 'After what?'], [0, 'That\'s what I asked. He said "just after."']] },
  { tags: ['gossip'], lines: [[0, 'Ebb has a sweetheart in Millhaven.'], [1, "The miller's son?"], [0, "The miller's daughter."], [1, 'Good for Ebb.'], [0, "And the miller's son is heartbroken, which is better gossip."]] },
  { tags: ['gossip'], lines: [[0, 'The reeve fell asleep in the cathedral during the sermon.'], [1, 'He always does.'], [0, 'This time he woke up in the vestry, tucked in a blanket.'], [1, 'Who carried him?'], [0, "Nobody owns up. The blanket's very old."]] },
  { tags: ['gossip'], lines: [[0, 'Garrow made a ring.'], [1, 'Garrow? He makes nails.'], [0, "It's tiny. He hides it in his apron and looks at it."], [1, 'For Agnes?'], [0, "He hasn't the nerve. It'll be ten years in that apron."]] },
  { tags: ['gossip'], lines: [[0, "Lady Isolde can't cook."], [1, "She's gentry. Why would she?"], [0, 'She tried. For the stranger. The town hall smelled of it for days.'], [1, 'What was it meant to be?'], [0, "Pie. It's in the well now."]] },
  { tags: ['gossip'], lines: [[0, "They say Corin's never been further than the crater."], [1, 'But his maps go everywhere.'], [0, 'He asks travellers in the inn and draws what they say.'], [1, 'And if they lie?'], [0, 'Then the map has a dragon in it.']] },
  { tags: ['gossip'], lines: [[0, 'Wren and the stranger went hunting in the Darkwood.'], [1, 'Wren hunts alone.'], [0, 'She came back talking. Three whole sentences.'], [1, 'Saints. She must like them.']] },
  { tags: ['gossip'], lines: [[0, 'Mistress Grimwald told the garrison her husband was ill.'], [1, 'Was he?'], [0, 'He was hiding in the flour bin with the good stock.'], [1, 'Did they look?'], [0, 'They looked at her. That was enough. They left.']] },
  // ------------------------------------------------- gossip with three
  { tags: ['gossip', 'trio'], lines: [[0, 'Have you heard about Hob?'], [1, 'The ribbons?'], [2, 'No, the bonnet.'], [0, 'He bought a bonnet now?'], [2, 'Old-fashioned. The kind they buried women in.'], [1, 'Oh, Hob.']] },
  { tags: ['gossip', 'trio'], lines: [[0, 'Who do you think the reeve fancies?'], [1, 'The Widow Harrow.'], [2, 'Mother Hesk.'], [0, 'Mother Hesk?'], [2, "He goes to the House of Mending for a tonic every day. He's never sick."], [1, "He's sick now, I'd say."]] },
  { tags: ['gossip', 'trio'], lines: [[0, 'Elsie says she saw the stranger without their shirt.'], [1, 'And?'], [2, 'She dropped a tray of ale.'], [0, 'Tobias took it out of her wages.'], [1, 'Worth it, she says.']] },
  { tags: ['gossip', 'trio'], lines: [[0, "I hear Wat's going down the cathedral stair."], [1, 'To impress Maud?'], [2, 'To impress Elsie.'], [0, 'To impress the both of them.'], [1, "He'll impress the dead first."], [2, "He'll get as far as the first landing and come back for a lamp."]] },
  // --------------------------------------------------------- the watch
  { tags: ['guard'], lines: [[0, "Who's got the crossbow tonight?"], [1, "Nobody. It's got no string."], [0, "Then who's got the string?"], [1, 'Hob borrowed it. For a kite.']] },
  { tags: ['guard'], lines: [[0, 'Something tried the cathedral door at the third hour.'], [1, 'From the street?'], [0, 'From the stair side. It knocked like it had manners.'], [1, 'Did you open it?'], [0, "I said nobody was home. It went away. I'm not proud of it."]] },
  { tags: ['guard'], lines: [[0, 'Draw your sword, {b}. Let me see the edge.'], [1, "It's clean."], [0, "It's rusted to the scabbard."], [1, "Then nothing's getting it off me, is it?"]] },
  { tags: ['guard'], lines: [[0, "Where is the old watch's banner now?"], [1, 'In the cellars under the fallen tower. In the Darkwood.'], [0, 'Why did nobody ever bring it home?'], [1, 'Everyone who went is still down there guarding it.']] },
  { tags: ['guard'], lines: [[0, 'Count the graves on your round, {b}.'], [1, 'Every night?'], [0, 'Every night. Then count them again at dawn.'], [1, 'And if the numbers differ?'], [0, 'Then you come and tell me. Quietly.']] },
  { tags: ['guard'], lines: [[0, 'The sergeant wants us drilling at dawn.'], [1, 'With what?'], [0, 'Spears. Two of them.'], [1, 'There are only two of us.'], [0, "Then we'll both be very dangerous."]] },
  { tags: ['guard'], lines: [[0, 'I walked the wall last night, and something walked beside me.'], [1, 'On the far side?'], [0, 'Below it. Step for step.'], [1, 'What did you do?'], [0, 'Stopped. It stopped. We stood there till cockcrow.']] },
  { tags: ['guard'], lines: [[0, "You're sweating, {b}."], [1, "It's a warm night."], [0, "There's frost on the cobbles."], [1, "Then I'm warm from the inside. Terror's good for that."]] },
  { tags: ['guard'], lines: [[0, 'The reeve wants a report on the graveyard.'], [1, 'Write "quiet."'], [0, "It isn't quiet."], [1, 'Write "quiet" bigger. He likes good news in big letters.']] },
  { tags: ['guard'], lines: [[0, 'If anything comes up the cathedral stair, we hold it at the door.'], [1, 'For how long?'], [0, 'As long as it takes.'], [1, 'Takes for what?'], [0, 'For the stranger to come up the stair behind it.']] },
  { tags: ['guard'], lines: [[0, 'I wanted to be one of the Sworn, as a child.'], [1, 'You?'], [0, 'The black plate. The horses. The V on the shield.'], [1, 'And now?'], [0, "Now I've seen what they hang under it."]] },
  { tags: ['guard'], lines: [[0, 'Hand me the lantern, {b}.'], [1, "It's lit."], [0, "It's lit green."], [1, "Then you can keep it. I'm not walking the yard with that."]] },
  { tags: ['guard'], lines: [[0, 'How many nights have you slept in your boots?'], [1, 'Every night since spring.'], [0, "Take them off tonight. I'll keep watch."], [1, 'And if I need to run?'], [0, "Then run barefoot. You'll be quicker frightened."]] },
  { tags: ['guard'], lines: [[0, "There's a little girl at the graveyard gate."], [1, 'At this hour? Whose is she?'], [0, "She says she's waiting for her mother."], [1, 'Then walk her home.'], [0, "She says this is home. Her name's on the third stone."]] },
  { tags: ['guard'], lines: [[0, 'The Sworn walk our rounds now, as well as us.'], [1, 'Helpful of them.'], [0, 'They walk them just after us.'], [1, 'Why?'], [0, 'To see that we walked them.']] },
  { tags: ['guard'], lines: [[0, "You look at that black knight as if you'd like to hit him."], [1, 'I would.'], [0, "Look at him as if you'd buy him a drink."], [1, "I'd poison it."], [0, 'Then look at him like that. But smaller.']] },
  { tags: ['guard'], lines: [[0, 'A man came to the north gate asking after the stranger.'], [1, 'A friend of theirs?'], [0, 'Black cloak. A V sewn on the lining.'], [1, 'What did you tell him?'], [0, "Wrong town. He didn't believe me. He left anyway. For now."]] },
  { tags: ['guard'], lines: [[0, 'What do you do when your torch goes out in the yard?'], [1, 'Light it again.'], [0, "With what? Your flint's in the barracks."], [1, "...I'll carry two torches from now on."]] },
  { tags: ['guard'], lines: [[0, 'I heard the cathedral breathing last night.'], [1, 'Breathing?'], [0, 'Cold air up the stair. Then warm. Then cold again.'], [1, 'A draught off that pit they talk of.'], [0, "A draught doesn't sigh, {b}."]] },
  { tags: ['guard'], lines: [[0, 'The sergeant cries at night, you know.'], [1, 'Brand? Never.'], [0, "Over the old watch's banner. Don't tell him I said so."], [1, "I'd cry too. I went near those cellars once."]] },
  { tags: ['guard'], lines: [[0, 'Something took the pig from the barracks pen.'], [1, 'A wolf?'], [0, 'It left the gate bolted.'], [1, 'And the pig?'], [0, 'Its collar was hung neat on the bolt. Like a thank-you.']] },
  { tags: ['guard'], lines: [[0, 'The stranger borrowed the barracks whetstone.'], [1, 'What for?'], [0, 'Sharpening. All night. Three swords.'], [1, 'Three?'], [0, 'The other two came up out of the crypts. Older than the town.']] },
  { tags: ['guard'], lines: [[0, 'New orders: nobody on the cathedral steps after dusk.'], [1, 'Not even the priest?'], [0, 'Especially the priest. She keeps trying to go down with a lamp.']] },
  { tags: ['guard'], lines: [[0, 'Halt! Who goes there?'], [1, "It's me, {a}."], [0, 'Prove it.'], [1, 'I owe you four coppers.'], [0, 'Pass, friend. And pay me.']] },
  { tags: ['guard'], lines: [[0, 'We need more hands on the watch.'], [1, "Who'd sign up?"], [0, 'Hob asked.'], [1, 'Hob? He talks to the mausoleum.'], [0, "Then he'll be good at keeping the peace with it."]] },
  { tags: ['guard'], lines: [[0, 'Hear that?'], [1, 'Hear what?'], [0, 'Exactly. Even the crows have stopped.'], [1, "Then something's coming."], [0, "Or it's here, and they're being polite about it."]] },
  { tags: ['guard'], lines: [[0, 'My mother wants me off the watch.'], [1, 'Wise woman.'], [0, "She says the dead don't pay pensions."], [1, 'Neither does the reeve.']] },
  { tags: ['guard'], lines: [[0, 'Tell me something cheerful, {b}.'], [1, 'The wall has held a hundred years.'], [0, 'And?'], [1, 'And it only has to hold one more night. Every night.']] },
  { tags: ['guard'], lines: [[0, 'I found boot prints going into the yard.'], [1, 'Whose?'], [0, 'Mine. From my round last night.'], [1, 'And coming out?'], [0, "There aren't any. And yet here I am. Explain that."]] },
  { tags: ['guard', 'trio'], lines: [[0, 'Three of us on the gate tonight.'], [1, 'Is that enough, {c}?'], [2, "For what's on the Downs? No."], [0, "For what's in the yard?"], [2, 'Also no.'], [1, 'Then why three?'], [0, 'So one of us can run and tell.']] },
  // ------------------------------------------ Lord Velscour's garrison
  { tags: ['velscour'], lines: [[0, 'Word from Blackvigil. From the Red Hand.'], [1, 'What word?'], [0, 'One. "Soon."'], [1, 'Soon what?'], [0, 'He never sends the second word. That is the point of him.']] },
  { tags: ['velscour'], lines: [[0, 'Do you dream, {b}?'], [1, 'Of the Keep. Always the Keep.'], [0, 'Good. It means it still has you.']] },
  { tags: ['velscour'], lines: [[0, 'Keep your gauntlets on in the village.'], [1, 'Why?'], [0, 'They must never see our hands. Hands look human.']] },
  { tags: ['velscour'], lines: [[0, 'The baker looked me in the eye this morning.'], [1, 'Shall we punish her?'], [0, 'No. I bought a loaf. Let her lie awake wondering why.']] },
  { tags: ['velscour'], lines: [[0, 'A villager asked me my name today.'], [1, 'And you answered?'], [0, "His. And his wife's. And his children's."], [1, 'He will not ask again.']] },
  { tags: ['velscour'], lines: [[0, 'Kneel, {b}.'], [1, 'Here? In the mud?'], [0, 'The V does not mind mud. Lower. Good.'], [1, 'May I rise?'], [0, 'Rise. And remember how far down that was.']] },
  { tags: ['velscour'], lines: [[0, 'What is in the basket?'], [1, 'Eggs, {a}. Only eggs.'], [0, 'Break one.'], [1, 'Why?'], [0, 'I like to watch things break. Good. Now the rest are safe. Go.']] },
  { tags: ['velscour'], lines: [[0, 'The Vigil has stood three hundred years.'], [1, 'And will stand three hundred more.'], [0, 'Say it as if you mean it.'], [1, 'It will stand when this village is grass.'], [0, 'Better.']] },
  { tags: ['velscour'], lines: [[0, 'Did you know our brother? The one in the crater?'], [1, 'We stood watch together at the Keep.'], [0, 'What was he like?'], [1, "Loyal. Loud. He'd want us to find who did it."], [0, 'Then we will. And we will be loud about it.']] },
  { tags: ['velscour'], lines: [[0, 'Lord Velscour does not sleep.'], [1, 'Then neither do we.'], [0, 'Not while that hole is still smoking.']] },
  { tags: ['velscour'], lines: [[0, 'That old man spat when I passed.'], [1, 'Shall I fetch him?'], [0, 'No. Chalk a small V on his door.'], [1, 'Only that?'], [0, 'He will find it at dawn and never sleep soundly again.']] },
  { tags: ['velscour'], lines: [[0, 'This town prays too much.'], [1, 'To its dead saints.'], [0, 'A saint is a dead man who was lucky in his stories.'], [1, 'And Lord Velscour?'], [0, 'He writes his own.']] },
  { tags: ['velscour'], lines: [[0, 'Do you hear the bell, {b}?'], [1, 'It rings for the dead.'], [0, 'Here it rings for the dead. At Blackvigil, it rings for us.']] },
  { tags: ['velscour'], lines: [[0, 'Who has been selling green ribbon?'], [1, 'The chandler, {a}.'], [0, 'Buy all she has left.'], [1, 'To burn?'], [0, 'To wear. Let them see their hope on us. Let them wonder.']] },
  { tags: ['velscour'], lines: [[0, 'You. Where are you going with that lamp?'], [1, 'To the cathedral, {a}. To pray.'], [0, 'At this hour?'], [1, 'The dead pray at this hour. I keep them company.'], [0, '...Go. Quickly. Before I think about that.']] },
  { tags: ['velscour'], lines: [[0, 'A Sworn does not run.'], [1, 'Not even from fire?'], [0, 'Our brother ran. A dozen strides.'], [1, 'And now?'], [0, 'And now he is a lesson. Learn it.']] },
  { tags: ['velscour'], lines: [[0, 'Polish my greaves.'], [1, "I'm not your squire."], [0, 'Today you are. Tomorrow you may be something else. Or nothing.'], [1, '...Where is the cloth?']] },
  { tags: ['velscour'], lines: [[0, 'A child was singing in the square.'], [1, 'A hymn?'], [0, 'A rhyme. About a star and a knight.'], [1, 'Shall we find the child?'], [0, 'We find the mother. Children learn their songs somewhere.']] },
  { tags: ['velscour'], lines: [[0, 'Count the villagers at the evening bell.'], [1, 'Why count them?'], [0, 'Count again tomorrow. When the number changes, we learn who went where.']] },
  { tags: ['velscour'], lines: [[0, 'What did you swear, the day you took the black?'], [1, 'Everything.'], [0, 'Everything what?'], [1, 'That is the oath. One word. Everything.'], [0, 'Mine was the same. I have nothing left over, either.']] },
  { tags: ['velscour'], lines: [[0, 'Your tithe is short, {b}.'], [1, 'The harvest was poor, {a}.'], [0, 'Then the next harvest pays for two.'], [1, "And if that one's poor too?"], [0, 'Then we take something that grows back faster.']] },
  { tags: ['velscour'], lines: [[0, 'Why does that woman leave bread at the crater?'], [1, 'For the birds, {a}.'], [0, 'No birds go near the crater.'], [1, 'For luck, then.'], [0, "Luck. Then she won't miss it when I take it."]] },
  { tags: ['velscour'], lines: [[0, 'They fear us, brother.'], [1, 'Good.'], [0, 'They fear the dead more.'], [1, 'Then we must stand closer to them than the dead do.']] },
  { tags: ['velscour'], lines: [[0, 'Who goes down the cathedral stair?'], [1, 'Nobody, {a}.'], [0, 'Somebody comes up it. Grey with dust, carrying old gold.'], [1, "I don't know who."], [0, 'You will know by morning.']] },
  { tags: ['velscour'], lines: [[0, 'The dread knights on the Downs report losses.'], [1, 'To what? Wolves?'], [0, 'To a stranger with a sword, who smiles while he works.'], [1, 'Then we take the smile first.']] },
  { tags: ['velscour'], lines: [[0, 'Do you miss the Keep?'], [1, 'I miss the quiet. Here they whisper all day.'], [0, 'At the Keep only the stones whisper.'], [1, 'And the stones know better than to say his name.']] },
  { tags: ['velscour'], lines: [[0, 'Lord Velscour gave me this blade with his own hand.'], [1, 'You saw him?'], [0, 'I knelt. His hand came down. I did not look up.'], [1, 'What was it like?'], [0, 'Cold, through the gauntlet. Like a promise kept.']] },
  { tags: ['velscour'], lines: [[0, 'Stop staring at my V, {b}.'], [1, 'Forgive me, {a}.'], [0, 'Look at the boots. The V is for those who have earned it.']] },
  { tags: ['velscour'], lines: [[0, 'The dead in the yard do not touch us.'], [1, 'No?'], [0, 'They pass us by like furniture.'], [1, 'Then what are we to them?'], [0, 'Do not think on it. Walk the round.']] },
  { tags: ['velscour'], lines: [[0, 'Write down every name in this village.'], [1, 'Every one? Why?'], [0, 'Lord Velscour likes to know what he owns.'], [1, "And the stranger's name?"], [0, 'Leave a space. We will fill it in red.']] },
  { tags: ['velscour', 'trio'], lines: [[0, 'Two of you, whispering. Explain yourselves.'], [1, 'We were only talking, {a}.'], [2, 'About the weather.'], [0, 'The weather is grey, {c}. You were smiling.'], [2, "Grey's lovely this time of year."], [0, 'Go home. Both of you. By separate streets.']] },
  // -------------------------------------------------------------- work
  { tags: ['worker'], lines: [[0, 'The reeve wants the cathedral stair bricked up.'], [1, 'With the stranger still down there?'], [0, 'After they come up.'], [1, "And if they don't come up?"], [0, 'Then we brick very, very slowly.']] },
  { tags: ['worker'], lines: [[0, 'Take the other end, {b}.'], [1, "Of the coffin? It's empty."], [0, "It's heavy for empty."], [1, "...Let's not open it to check."]] },
  { tags: ['worker'], lines: [[0, "Who digs the graves, now the sexton's gone?"], [1, 'We do. Tuppence a hole.'], [0, 'And filling them in?'], [1, "Thruppence. Filling's the hard part. They keep trying to help."]] },
  { tags: ['worker'], lines: [[0, 'Three days, to shift one stone.'], [1, "It's one stone."], [0, "It's one stubborn stone."], [1, "It came out of the crater. It doesn't want to go anywhere else."]] },
  { tags: ['worker'], lines: [[0, 'I sent six empty barrels to the inn.'], [1, 'And?'], [0, 'They sent one back full.'], [1, 'Of ale?'], [0, 'Of something that sloshes the wrong way when you tip it.']] },
  { tags: ['worker'], lines: [[0, 'Fine hide, this one.'], [1, 'What animal?'], [0, "I don't ask Wren. She doesn't ask me what I do with them."], [1, 'Seems fair.']] },
  { tags: ['worker'], lines: [[0, "The horses won't go in the end stall."], [1, 'Why not?'], [0, "Something's been sleeping in the hay."], [1, 'What sort of something?'], [0, 'A long sort. With a dent where its head goes.']] },
  { tags: ['worker'], lines: [[0, "Hoop's sprung again."], [1, 'Third today.'], [0, "It's the oak from the Darkwood. It remembers being a tree."], [1, "Then remind it it's a barrel now."]] },
  { tags: ['worker'], lines: [[0, 'Payday!'], [1, 'From the reeve?'], [0, 'From the reeve. In turnips.'], [1, 'How many?'], [0, 'Enough to be sick of turnips. Not enough to live on them.']] },
  { tags: ['worker'], lines: [[0, 'Sit with me, {b}. Eat something.'], [1, 'On the coffin?'], [0, "It's the only clean seat in Bellmourn."], [1, 'Whose is it?'], [0, "Nobody's yet. That's why it's clean."]] },
  { tags: ['worker'], lines: [[0, 'The Sworn make us carry water up to the barracks.'], [1, 'Do they drink it?'], [0, 'The buckets come back full. Every single day.'], [1, 'Then why carry it?'], [0, 'To see that we will.']] },
  { tags: ['worker'], lines: [[0, 'Sister Odile pays a silver to sweep the crypt stair.'], [1, 'A silver!'], [0, 'For the first three steps.'], [1, 'And the fourth?'], [0, 'Nobody has earned the fourth yet.']] },
  { tags: ['worker'], lines: [[0, 'Hold the ladder, {b}.'], [1, "I've got it."], [0, "You're holding the wrong ladder."], [1, 'Then whose is this?'], [0, "Nobody's. Let go of it slowly. Don't look up."]] },
  { tags: ['worker'], lines: [[0, 'Sing us a work song, {b}.'], [1, 'I only know funeral songs.'], [0, "Then sing one fast. We'll dig to it."]] },
  { tags: ['worker'], lines: [[0, 'Reeve wants the bell rope mended.'], [1, "It isn't frayed."], [0, "It's chewed."], [1, 'By rats?'], [0, "From the top end, {b}. The rats don't go up there."]] },
  { tags: ['worker'], lines: [[0, 'We bricked up the vestry window.'], [1, 'Why?'], [0, 'Something kept looking in.'], [1, 'From the street?'], [0, 'From inside the cathedral. Looking out at us.']] },
  { tags: ['worker'], lines: [[0, "The ox won't pull past the graveyard."], [1, 'Blindfold it.'], [0, "It's blindfolded. It counts the steps and stops at the gate."], [1, 'Clever ox.'], [0, 'Cleverer than us. We go past it every day.']] },
  { tags: ['worker'], lines: [[0, 'My father dug the cellar of the inn.'], [1, 'Hard work.'], [0, 'He found another cellar under it. Older.'], [1, 'And under that?'], [0, 'He stopped digging. He was a sensible man.']] },
  { tags: ['worker'], lines: [[0, 'Help me shift the woodpile?'], [1, "What's under it?"], [0, "Last winter's logs. And whatever's lived there since."], [1, "I'll take the top. You take the bottom."]] },
  { tags: ['worker'], lines: [[0, "There's a nail in my boot."], [1, 'Pull it out.'], [0, "It's a coffin nail. I'd rather not touch it."], [1, "Then walk on it till it's somebody else's problem."]] },
  { tags: ['worker'], lines: [[0, 'The reeve wants us to work on the holy day.'], [1, 'And the Sworn?'], [0, 'The Sworn want it worked twice.'], [1, 'We could work it once and look busy the second time.'], [0, "That's what I've been doing all my life."]] },
  { tags: ['worker'], lines: [[0, "I've been carting stone from the crater all week."], [1, 'For what?'], [0, "The reeve's new wall. Round the town hall."], [1, 'Not round the town?'], [0, 'Round the town hall, {b}. He knows where he lives.']] },
  { tags: ['worker'], lines: [[0, 'I hate the night shift.'], [1, 'Same work as the day.'], [0, 'Same work. Different company.'], [1, 'What company?'], [0, 'The kind that stands just past the lamplight and watches you lift.']] },
  { tags: ['worker'], lines: [[0, "I've finished the new gate!"], [1, "It's lovely."], [0, 'It swings both ways.'], [1, 'Is that good?'], [0, "Depends who's pushing."]] },
  { tags: ['worker'], lines: [[0, 'Have you seen my good shovel?'], [1, 'By the yard wall.'], [0, "I didn't leave it there."], [1, "It's standing up. In fresh earth. Like a marker."], [0, "Then it's not my shovel any more. Leave it."]] },
  { tags: ['worker'], lines: [[0, "How's the arm, {b}?"], [1, "Hesk says I'll lift again by spring."], [0, 'And till spring?'], [1, "Till spring I'll point at things and complain."], [0, "You'll be wonderful at it."]] },
  { tags: ['worker'], lines: [[0, "Everyone's buying bolts for their doors."], [1, 'Good trade for the smith.'], [0, "Good trade for us. Somebody's got to fit them."], [1, "And when the bolts don't hold?"], [0, "Then they'll want new doors. We're set for life."]] },
  { tags: ['worker', 'trio'], lines: [[0, 'On three. One, two...'], [1, 'Wait. Which way are we lifting?'], [2, 'Up.'], [1, 'I mean whose way is up?'], [0, "The coffin's way. Lift!"], [2, "It's lighter than it was this morning."], [1, 'Put it down. Put it down now.']] },
  // ----------------------------------------- merchants and their wares
  { tags: ['merchant'], lines: [[0, "Lamp oil's the thing this season."], [1, 'Not candles?'], [0, 'Candles go out when the dead pass. Oil only gutters.'], [1, 'Put that on a sign.'], [0, 'I did. Forty flasks by noon.']] },
  { tags: ['merchant'], lines: [[0, 'The stranger sold me a crown.'], [1, 'A crown!'], [0, "Small. Bent. Off a founder's skull, they said."], [1, 'What did you give for it?'], [0, "Too much. And I'd give it again to see it on my shelf."]] },
  { tags: ['merchant'], lines: [[0, 'Five coppers.'], [1, 'Three.'], [0, 'Five, and I throw in a prayer.'], [1, 'Three, and keep your prayer.'], [0, 'Four, and I pray for you anyway. No charge.'], [1, '...Done.']] },
  { tags: ['merchant'], lines: [[0, 'The garrison wants a tenth of my stall.'], [1, 'A tenth of your takings?'], [0, 'A tenth of the stall. They took a leg off it.'], [1, "So that's why it leans."]] },
  { tags: ['merchant'], lines: [[0, 'Who on earth buys bone dust?'], [1, 'The alchemist.'], [0, 'By the pound?'], [1, "By the pinch. And only from ringers. He's very particular."]] },
  { tags: ['merchant'], lines: [[0, 'Business is good, {b}.'], [1, 'With the roads shut?'], [0, "Folk buy more when they're frightened."], [1, "And when they're terrified?"], [0, "They buy on credit. That's the bad part."]] },
  { tags: ['merchant'], lines: [[0, "Rope's sold out again."], [1, "Everyone's climbing something."], [0, "Or tying something down. I've stopped asking which."]] },
  { tags: ['merchant'], lines: [[0, 'A woman bought every mirror I had.'], [1, 'Vain?'], [0, 'She hung them on her fence, facing the graveyard.'], [1, 'Why?'], [0, "She says the dead can't bear to see themselves."], [1, 'Does it work?'], [0, "She's sold me back two. Cracked from the far side."]] },
  { tags: ['merchant'], lines: [[0, 'Got any garlic?'], [1, "Garlic's for the other sort of dead."], [0, 'What sort are ours?'], [1, 'The sort that eats it.']] },
  { tags: ['merchant'], lines: [[0, "I've a new line of goods. Grave bells."], [1, "What's a grave bell?"], [0, 'A string from the coffin to a bell above. In case you wake.'], [1, 'Has anyone rung one?'], [0, 'Three. I sold six more the same morning.']] },
  { tags: ['merchant'], lines: [[0, "Credit's closed, {b}."], [1, 'Since when?'], [0, 'Since my last three debtors went into the Darkwood.'], [1, 'They might come back.'], [0, "They might. I won't be the one to go and ask."]] },
  { tags: ['merchant'], lines: [[0, 'What do adventurers buy, mostly?'], [1, 'Rope, oil, bread.'], [0, 'And what do they sell?'], [1, 'Everything they own. On their way out of town.']] },
  { tags: ['merchant'], lines: [[0, "This sword's from the Hall of the Founders."], [1, 'How do you know?'], [0, "It came with a curse. A very old one. Founders' quality."], [1, 'And the price?'], [0, 'Reduced. On account of the curse.']] },
  { tags: ['merchant'], lines: [[0, 'Lady Isolde wants black silk.'], [1, "For mourning? Who's died?"], [0, "She hasn't decided. She likes to be ready."]] },
  { tags: ['merchant'], lines: [[0, 'The Sworn pay in Blackvigil scrip.'], [1, 'Is it worth anything?'], [0, 'At Blackvigil.'], [1, 'Will you go and spend it there?'], [0, "I'll paper the privy with it. Very slowly."]] },
  { tags: ['merchant'], lines: [[0, 'A man offered me his soul for a lamp.'], [1, 'Did you take it?'], [0, 'What would I do with a soul? I made him pay in coin.'], [1, 'Did he have coin?'], [0, "Turned out he'd been hiding both."]] },
  { tags: ['merchant'], lines: [[0, "The ledger doesn't balance."], [1, 'By how much?'], [0, 'One copper.'], [1, 'Let it go.'], [0, "It's the same copper. It comes back every morning. I've marked it."]] },
  { tags: ['merchant'], lines: [[0, 'What sells best in Bellmourn, {b}?'], [1, 'Bread.'], [0, 'After bread?'], [1, 'Locks. Then shovels.'], [0, 'And after shovels?'], [1, 'More locks.']] },
  { tags: ['merchant'], lines: [[0, "I've a crate of holy water."], [1, 'Blessed?'], [0, 'By a priest.'], [1, 'Which priest?'], [0, 'One who walked past it slowly.']] },
  { tags: ['merchant'], lines: [[0, 'Trade you a lamp for that knife.'], [1, "What's wrong with the lamp?"], [0, 'Nothing.'], [1, "What's wrong with my knife?"], [0, 'Nothing. I just like the thought of you with a lamp, out there.']] },
  { tags: ['merchant'], lines: [[0, 'What do you sell a saint, {b}?'], [1, 'Nothing. Saints have everything.'], [0, "Socks. Nobody ever thinks of a saint's socks."], [1, 'Then knit him some.'], [0, 'Green ones. Already started.']] },
  { tags: ['merchant'], lines: [[0, 'A caravan came through from the south.'], [1, 'At last!'], [0, 'Two carts. One driver.'], [1, "Where's the rest of them?"], [0, "He won't say. He wants to sell me the empty cart."]] },
  { tags: ['merchant'], lines: [[0, 'Ghast teeth! Fresh from the Gloamhollow!'], [1, 'Who pulled them?'], [0, 'The stranger did.'], [1, 'Out of a ghast?'], [0, 'Out of their own leg. Price is the same either way.']] },
  { tags: ['merchant'], lines: [[0, 'Two coppers for a candle? It was one last month.'], [1, 'And last month the dead stayed in.'], [0, "What's that to do with candles?"], [1, 'Everything, {a}. Everything is to do with candles now.']] },
  { tags: ['merchant'], lines: [[0, 'I could sell that cloak of yours, {b}.'], [1, "It's my only cloak."], [0, "To the stranger. They've been through three."], [1, 'What happens to them?'], [0, "Things down there grab at the hem. Sell it short, I'd say."]] },
  { tags: ['merchant'], lines: [[0, "Who'd buy a coffin before they need it?"], [1, 'Half the town.'], [0, 'Why?'], [1, 'Price goes up after. Everybody knows that.']] },
  { tags: ['merchant'], lines: [[0, "I've stopped selling salt."], [1, 'Why? It sells.'], [0, 'Folk put it on their doorsteps and come back for more every day.'], [1, "That's good business."], [0, "It's being eaten, {b}. Something comes and licks it up."]] },
  { tags: ['merchant', 'trio'], lines: [[0, 'Fresh bread, fair candles, fine rope!'], [1, 'How much for the rope?'], [2, "Don't. I bought her rope last week."], [0, 'Good rope!'], [2, "It held. It's what it held that I didn't care for."], [1, '...How much for the bread?']] },
  // --------------------------------------------------------- the smith
  { tags: ['smith'], lines: [[0, "Sworn steel won't take an edge."], [1, 'Too hard?'], [0, 'Too proud. It wants to be its own sword, not mine.']] },
  { tags: ['smith'], lines: [[0, "The bell founder's moulds are in my cellar."], [1, 'The man who cast our bell?'], [0, 'My great-great-grandfather.'], [1, 'Did he cast the first bell too?'], [0, "He refused. That's why Bellmourn has a second."]] },
  { tags: ['smith'], lines: [[0, "Want to know a smith's secret, {b}?"], [1, 'Go on.'], [0, 'Water quenches. Oil tempers.'], [1, 'And?'], [0, "Tears do neither. I've tried."]] },
  { tags: ['smith'], lines: [[0, "The stranger's blade came back notched like a saw."], [1, 'What did they hit?'], [0, 'Bone. Old bone, hard as oak.'], [1, 'Can you mend it?'], [0, 'I can make it angrier.']] },
  { tags: ['smith'], lines: [[0, 'Fifty horseshoes for the garrison.'], [1, "Fifty? They've six horses."], [0, "They say they're expecting more riders."], [1, 'From Blackvigil?'], [0, "I'm shoeing very slowly this month."]] },
  { tags: ['smith'], lines: [[0, 'My hammer sounds wrong today.'], [1, 'Wrong how?'], [0, 'Every stroke has an echo from below.'], [1, 'From the cathedral?'], [0, 'Someone down there is forging too. A beat behind me.']] },
  { tags: ['smith'], lines: [[0, 'Agnes asked me to mend her oven door.'], [1, 'And?'], [0, 'I was there four hours.'], [1, "It's a door."], [0, "It's a very complicated door."]] },
  { tags: ['smith'], lines: [[0, 'Want to learn the forge, {b}?'], [1, 'Maybe.'], [0, "First rule: don't touch the hot end."], [1, 'Which end is that?'], [0, 'The first year? Both of them.']] },
  { tags: ['smith'], lines: [[0, "I'm forging a sword without a name."], [1, 'Every sword has a name.'], [0, 'This one gets its name from the first thing it kills.'], [1, "And if that's a rat?"], [0, "Then it's Ratbane, and it'll be a happy sword."]] },
  { tags: ['smith'], lines: [[0, 'Bring that scythe here, {b}.'], [1, "It's for the harvest. It's sharp enough."], [0, 'Sharpen it anyway. Harvests here bite back.']] },
  { tags: ['smith'], lines: [[0, "The forge wouldn't light this morning."], [1, 'Damp coal?'], [0, 'Dry coal. Dry kindling. Dry flint.'], [1, 'Then why?'], [0, "Something sat on the hearth all night. It's cold as a grave."]] },
  { tags: ['smith'], lines: [[0, 'The Sworn want their armour mended.'], [1, 'Will you do it?'], [0, "I'll mend it. Every rivet a hair loose."], [1, "They'll notice."], [0, 'Not until the day it matters.']] },
  { tags: ['smith'], lines: [[0, "The bell rope's woven with iron wire, you know."], [1, 'Why?'], [0, 'My grandfather did it. So nothing can climb it from the bottom.'], [1, "The bottom's just the tower floor."], [0, 'Is it?']] },
  { tags: ['smith'], lines: [[0, 'What will it be, {b}? A blade? A buckle?'], [1, 'A key.'], [0, 'To what?'], [1, "My own front door. I'm locked out."], [0, 'Who locked it?'], [1, "Something inside. It won't say."]] },
  { tags: ['smith'], lines: [[0, 'I could make the stranger a shield.'], [1, 'Out of what?'], [0, 'The door of the Burnt House. Oak and iron.'], [1, 'It survived the fire.'], [0, "That's the point. It's survived worse than anything on the Downs."]] },
  { tags: ['smith'], lines: [[0, 'The reeve wants a new weathervane.'], [1, 'Shaped like?'], [0, 'A cockerel.'], [1, 'Nice.'], [0, "The last one turned to face the yard and wouldn't turn back. This one's heavier."]] },
  { tags: ['smith'], lines: [[0, 'Bring me any horseshoe you find.'], [1, 'For luck?'], [0, "For iron. The dead don't care for iron. I'm making a fence."], [1, 'Round the graveyard?'], [0, 'Round my bed.']] },
  { tags: ['smith'], lines: [[0, 'What makes good steel, {b}?'], [1, 'Good iron?'], [0, 'Good iron, a good fire, and someone you want to keep alive.']] },
  { tags: ['smith'], lines: [[0, "The founders' swords were bronze, you know."], [1, 'How do you know?'], [0, 'The stranger brought one up. Green as a pond.'], [1, 'Is it worth anything?'], [0, 'It cut my thumb. So yes.']] },
  { tags: ['smith'], lines: [[0, 'The sorcerers on the Downs wear iron rings.'], [1, 'What for?'], [0, "To hold their spells. I've got two."], [1, 'And?'], [0, 'They hum at night. I keep them in a bucket of water. It boils.']] },
  { tags: ['smith'], lines: [[0, "Your plough blade's bent like a smile, {b}."], [1, 'It hit something in the bottom field.'], [0, 'A stone?'], [1, 'A coffin lid.'], [0, "Out there? There's no yard out there."], [1, "That's what I keep telling it."]] },
  { tags: ['smith'], lines: [[0, "Folk think a smith's work is all noise."], [1, "Isn't it?"], [0, "The loud part's easy. The quiet part's listening to the steel cool."], [1, 'What does it say?'], [0, 'Mostly "not yet."']] },
  { tags: ['smith'], lines: [[0, 'Coin or trade, {b}?'], [1, 'Trade. A cheese.'], [0, 'For a blade?'], [1, 'A big cheese.'], [0, 'Millhaven cheese?'], [1, 'The last one in Bellmourn.'], [0, "...Done. Don't tell anyone what I'm worth."]] },
  { tags: ['smith'], lines: [[0, 'They want the spearheads blessed again.'], [1, "Didn't the priest bless the last lot?"], [0, 'She did. They rusted overnight.'], [1, 'Too much blessing?'], [0, 'Not enough. Something down there drank it off them.']] },
  { tags: ['smith'], lines: [[0, 'Pump the bellows, {b}.'], [1, 'Harder?'], [0, 'Steady. Steady as breathing.'], [1, 'Whose breathing?'], [0, "Yours. The forge breathes on its own after dark. I don't like it to."]] },
  { tags: ['smith'], lines: [[0, "A sword's only as good as the hand on it."], [1, "And the stranger's hand?"], [0, 'I watched them hold one of mine. They held it like an old friend.'], [1, 'Is that good?'], [0, "It means they've buried a few friends. Yes. It's good."]] },
  { tags: ['smith'], lines: [[0, "The Sworn's armour is forged with something in it."], [1, 'Something?'], [0, 'Ash. Not wood ash. Finer.'], [1, 'Bones?'], [0, 'Hymns, maybe. Whatever it is, it screams in my fire.']] },
  { tags: ['smith', 'trio'], lines: [[0, 'Who wants first go at the grindstone?'], [1, 'Me.'], [2, 'I was here first.'], [0, 'Settle it fair.'], [1, "Whoever's blade is duller."], [2, "Mine was stuck in a ghast's back all week. It's very dull."], [1, '...You go first.']] },
  // --------------------------------------------------------- the baker
  { tags: ['baker'], lines: [[0, 'No flour from Millhaven for a fortnight.'], [1, 'What are you baking with?'], [0, 'Acorns, barley and spite.'], [1, 'How does it taste?'], [0, 'Mostly of spite.']] },
  { tags: ['baker'], lines: [[0, "Funeral bread's selling faster than the plain."], [1, "That's grim."], [0, "It's sweeter. Folk say the dead deserve the sugar."], [1, 'And the living?'], [0, 'Buy it too. Grief has a sweet tooth.']] },
  { tags: ['baker'], lines: [[0, "I'm up at three every morning to bake."], [1, "Doesn't the dark frighten you?"], [0, "The oven's a big warm mouth, and it's on my side."], [1, 'And nothing comes near?'], [0, 'Nothing that wants to stay cold.']] },
  { tags: ['baker'], lines: [[0, "Somebody's been at the dough in the night."], [1, 'Rats?'], [0, 'Fingerprints. Small ones. Cold ones.'], [1, 'A child?'], [0, "One that's been gone a long while, and misses bread."]] },
  { tags: ['baker'], lines: [[0, 'Taste this, {b}.'], [1, 'Lovely. What is it?'], [0, 'Dark rye and caraway. For the garrison.'], [1, 'And what did you put in theirs?'], [0, 'Onions. Heaps of onions. Let them breathe that inside a helm all day.']] },
  { tags: ['baker'], lines: [[0, 'This bakehouse is older than the bell tower.'], [1, 'Never.'], [0, "My grandmother's grandmother baked for the founders."], [1, 'And do the founders still come for their loaves?'], [0, "Only on Founders' Feast. And they never pay."]] },
  { tags: ['baker'], lines: [[0, 'Buns for the children, {b}.'], [1, 'Free?'], [0, 'Free, if they keep out of the graveyard.'], [1, "And if they don't?"], [0, 'Then they pay double, and I tell their mothers.']] },
  { tags: ['baker'], lines: [[0, 'My sourdough starter is forty years old.'], [1, 'It must be strong.'], [0, 'It bit me.'], [1, "Bread doesn't bite."], [0, 'Mine was raised in Bellmourn.']] },
  { tags: ['baker'], lines: [[0, 'The stranger ate a whole loaf on my step.'], [1, 'Hungry.'], [0, "Ate it like they'd forgotten what bread was."], [1, 'Down in the dark too long.'], [0, 'I gave them another. They wept over that one.']] },
  { tags: ['baker'], lines: [[0, "Soul cakes for Souls' Night."], [1, 'What goes in them?'], [0, 'Currants, cloves, and a name pressed into the top.'], [1, 'Whose name?'], [0, "Whoever you'd like to stay down."]] },
  { tags: ['baker'], lines: [[0, 'Hold the peel, {b}.'], [1, 'The what?'], [0, 'The big wooden spade, for the oven.'], [1, "It's heavier than a sword."], [0, "And it's killed more hunger than any sword in the realm."]] },
  { tags: ['baker'], lines: [[0, 'I burnt every loaf this morning.'], [1, 'Every one?'], [0, 'The bell rang while I was proving and I lost the hour.'], [1, 'Which hour did it ring?'], [0, 'None. It rang between them.']] },
  { tags: ['baker'], lines: [[0, 'Mind the goose, {b}.'], [1, 'Since when have you a goose?'], [0, "She guards the bakehouse. Nothing's got in since spring."], [1, 'Not even the dead?'], [0, "Especially not the dead. She can't abide them."]] },
  { tags: ['baker'], lines: [[0, 'My goose hissed at the stranger.'], [1, 'Did they run?'], [0, 'They bowed to her.'], [1, 'And?'], [0, "She let them by. She's never let anyone by. Not even me."]] },
  { tags: ['baker'], lines: [[0, 'The garrison wants white bread only.'], [1, "White flour's dear."], [0, 'They pay with a look.'], [1, 'What sort of look?'], [0, 'The kind that says "or else." Dearest coin there is.']] },
  { tags: ['baker'], lines: [[0, 'The reeve wants a cake for Founding Day.'], [1, 'Shaped like what?'], [0, 'The cathedral.'], [1, 'With the stair?'], [0, 'I put a little hole in the floor. Nobody laughed but me.']] },
  { tags: ['baker'], lines: [[0, 'I dreamt I baked a loaf so big it filled the Gulf.'], [1, 'The pit under the cathedral?'], [0, 'And the dead climbed out on it, eating as they came.'], [1, 'A bad dream, then.'], [0, 'No. They looked so happy. I woke up crying.']] },
  { tags: ['baker'], lines: [[0, 'The bees left the hives on the Downs. All in one night.'], [1, 'Where to?'], [0, 'East. Every one. As far from the Keep as wings can carry.'], [1, 'Sensible bees.'], [0, 'No honey cakes this year. Sensible bees.']] },
  { tags: ['baker'], lines: [[0, "I can't bake on holy days."], [1, 'Why not?'], [0, "The oven's been blessed. It refuses."], [1, "Ovens can't refuse."], [0, "It won't draw. Smoke out the front. The saints are stubborn."]] },
  { tags: ['baker'], lines: [[0, 'Hand me the salt, {b}.'], [1, 'Here.'], [0, "Not that salt. That's the doorstep salt."], [1, "What's the difference?"], [0, "The doorstep salt's been prayed over. You don't eat that."]] },
  { tags: ['baker'], lines: [[0, 'Millhaven used to send me their best wheat.'], [1, 'And now?'], [0, 'Now they send a boy with a note: "send help."'], [1, 'What do you send back?'], [0, "Bread. It's what I've got."]] },
  { tags: ['baker'], lines: [[0, 'Whose wedding cake is this, do you think?'], [1, 'Is anyone getting married?'], [0, "Nobody's asked yet. I'm baking hopefully."], [1, 'Who are you hoping for?'], [0, 'Anyone. A wedding is a week without funerals.']] },
  { tags: ['baker'], lines: [[0, 'Flour in my hair, flour in my bed.'], [1, 'Flour everywhere.'], [0, 'Even the ghost in my loft is white with it.'], [1, "You've a ghost?"], [0, 'A very well-floured ghost. You can see her coming.']] },
  { tags: ['baker'], lines: [[0, 'You look thin, {b}.'], [1, "I'm eating."], [0, 'Eating what?'], [1, 'Worry, mostly.'], [0, 'Here. Worry goes down better with butter.']] },
  { tags: ['baker'], lines: [[0, 'Bread for the Sworn goes up the hill at dawn.'], [1, 'You bake for them?'], [0, "I bake for everyone. Bread doesn't choose sides."], [1, 'And the baker?'], [0, 'The baker chooses which loaves she drops in the mud.']] },
  { tags: ['baker'], lines: [[0, 'Which do you like better, {b}? Crust or crumb?'], [1, 'Crumb.'], [0, 'Wrong. Crust.'], [1, 'Why?'], [0, 'Crust keeps. Crumb is soft and goes first. Be crust.']] },
  { tags: ['baker', 'trio'], lines: [[0, 'Last three buns.'], [1, "I'll have one."], [2, "And I'll have one."], [0, 'And the third?'], [1, 'For the stranger.'], [2, 'For the stranger.'], [0, "Then I'll eat it myself, and they can come earlier tomorrow."]] },
  // -------------------------------------------------------- the healer
  { tags: ['healer'], lines: [[0, 'Gravebloom only grows on the kind graves.'], [1, 'Which are the kind ones?'], [0, "The ones that don't open."], [1, 'How do you pick it?'], [0, 'Quickly. And I say thank you.']] },
  { tags: ['healer'], lines: [[0, 'Hold still, {b}. This will sting.'], [1, 'What is it?'], [0, 'Vinegar, wormwood, and a little bad news.'], [1, 'What bad news?'], [0, "It'll sting twice as much as I said."]] },
  { tags: ['healer'], lines: [[0, 'A bite from the dead goes green by the second day.'], [1, 'And by the third?'], [0, 'By the third you stop asking questions. So come on the first.']] },
  { tags: ['healer'], lines: [[0, 'A girl in the low houses had her baby in the night.'], [1, 'Healthy?'], [0, 'Loud. Screamed louder than the bell.'], [1, 'Is that good?'], [0, 'Anything that can outshout the bell will do well here.']] },
  { tags: ['healer'], lines: [[0, 'The stranger came to me with three ribs cracked.'], [1, 'Three!'], [0, 'And asked if they could go back down after supper.'], [1, 'What did you say?'], [0, "After breakfast. I'm not a monster."]] },
  { tags: ['healer'], lines: [[0, "You've been sleepwalking, {b}."], [1, 'How would you know?'], [0, 'You passed my window at midnight. Toward the yard.'], [1, 'Saints. Did I come back?'], [0, "You're here, aren't you? Mostly."]] },
  { tags: ['healer'], lines: [[0, 'Leeches, {b}?'], [1, 'For what?'], [0, "For whatever you've got. They're hungry, and they're cheap."]] },
  { tags: ['healer'], lines: [[0, "Sister Odile hasn't slept since the crater."], [1, 'Praying?'], [0, 'Reading. Every verse twice.'], [1, "Can't you give her something?"], [0, 'I gave her a sleeping draught. She read the label instead.']] },
  { tags: ['healer'], lines: [[0, 'Bring me cobwebs, {b}.'], [1, 'Cobwebs?'], [0, 'For the bleeding. Clean ones. Not from the cathedral.'], [1, 'Why not those?'], [0, "The spiders there aren't spiders."]] },
  { tags: ['healer'], lines: [[0, 'Do you want a cure for fear, {b}?'], [1, 'Is there one?'], [0, 'Company. And a strong cup of something.'], [1, 'Which works better?'], [0, "Company. The cup's quicker."]] },
  { tags: ['healer'], lines: [[0, 'I dressed a ghast scratch on the stranger.'], [1, 'Will it heal?'], [0, "It's healing in lines. Like writing."], [1, 'What does it say?'], [0, "I'm too old to learn that language, and I won't start now."]] },
  { tags: ['healer'], lines: [[0, 'Every draught I brew goes to the stranger now.'], [1, 'And the rest of us?'], [0, "You're not going down there. You can have chamomile."]] },
  { tags: ['healer'], lines: [[0, 'Two spoons at bedtime, {b}.'], [1, 'What does it do?'], [0, 'Stops the dreams.'], [1, 'All of them?'], [0, "The bad ones. The good ones you'll have to manage yourself."]] },
  { tags: ['healer'], lines: [[0, 'Mind that cough.'], [1, "It's only the damp."], [0, "It's crypt dust. You've been by the cathedral drains."], [1, 'How can you tell?'], [0, 'Your cough has an echo.']] },
  { tags: ['healer'], lines: [[0, 'Hot water, {b}! Quickly!'], [1, "Who's hurt?"], [0, 'Nobody yet. The bell just rang twice. Somebody will be.']] },
  { tags: ['healer'], lines: [[0, "I've buried more patients than I've saved this year."], [1, "That's not your fault, {a}."], [0, 'I know it. But they still come by to complain.']] },
  { tags: ['healer'], lines: [[0, 'Nettle, yarrow, comfrey.'], [1, 'For the stranger?'], [0, "For their satchel. They'll want all three at the Gulf."], [1, 'Why the Gulf?'], [0, 'That bridge sways, they tell me. Bruises, mostly. And worse.']] },
  { tags: ['healer'], lines: [[0, 'My mother taught me to stitch.'], [1, 'Wounds?'], [0, "Shrouds. A wound's just a shroud you get to take out after."]] },
  { tags: ['healer'], lines: [[0, "The Sworn won't let me treat them."], [1, 'Too proud?'], [0, "They won't take off their armour."], [1, "What's under it?"], [0, "That's half the reason I'd like to treat them."]] },
  { tags: ['healer'], lines: [[0, "There's a fever in the low houses."], [1, 'Bad?'], [0, "The kind that makes you hear the bell when it isn't ringing."], [1, 'Is there a cure?'], [0, 'Wool in the ears. Thick curtains. And someone silencing the thing for good.']] },
  { tags: ['healer'], lines: [[0, 'Sit down, {b}, before you fall.'], [1, "I'm well."], [0, "You're grey. You've been crying."], [1, "It's nothing."], [0, "Grief's never nothing. Sit. Tell an old woman."]] },
  { tags: ['healer'], lines: [[0, 'Poppy for the pain.'], [1, 'Not too much.'], [0, 'Enough to stop the pain. Not enough to stop the heart.'], [1, "It's a fine line."], [0, "I've walked it fifty years. I know every stone."]] },
  { tags: ['healer'], lines: [[0, 'A boy came in with a bite on his ankle.'], [1, 'A dog?'], [0, 'From the yard. Something reached up out of the ground.'], [1, 'Will he be all right?'], [0, "He'll live. He'll walk a long way round the yard from now on."]] },
  { tags: ['healer'], lines: [[0, 'I keep a jar of teeth, {b}.'], [1, 'Whose teeth?'], [0, "Everyone in Bellmourn I've ever pulled one from."], [1, 'Why?'], [0, "So I know who's who. After. When they come back."]] },
  { tags: ['healer'], lines: [[0, 'Wash your hands, {b}.'], [1, "They're clean."], [0, "They've been near the yard. What's there comes in on you."], [1, 'Twice, then.'], [0, 'Three times. And the fingernails.']] },
  { tags: ['healer'], lines: [[0, 'Odile and I argue about the dead.'], [1, 'About what?'], [0, 'She says pray for them. I say bandage the living.'], [1, "Who's right?"], [0, "We both do both, when the other isn't looking."]] },
  { tags: ['healer', 'trio'], lines: [[0, "Who's next?"], [1, 'Me. A splinter.'], [2, 'Me. A bite.'], [0, 'The bite first. Sit down, {c}.'], [1, "It's a very big splinter."], [0, 'The bite first, {b}.']] },
  // -------------------------------------------------------- the hunter
  { tags: ['hunter'], lines: [[0, "My grandfather's axe is still in the Trollhole."], [1, 'After forty winters?'], [0, 'Gnarlgut picks his teeth with it, they say.'], [1, "Then he'll be wanting new teeth when the stranger's done."]] },
  { tags: ['hunter'], lines: [[0, 'I set twelve snares last night.'], [1, 'How many caught?'], [0, 'Eleven empty. One sprung and tied in a bow.'], [1, 'By what?'], [0, 'Something with clever fingers and no use for rabbits.']] },
  { tags: ['hunter'], lines: [[0, 'One owl still calls in the Darkwood.'], [1, 'Only one?'], [0, "It calls in my uncle's whistle. The one he gave the day he went in."], [1, "Then don't answer it."], [0, 'I whistle back the second half. It goes quiet.']] },
  { tags: ['hunter'], lines: [[0, 'Wolf prints round the Barrow of Saint Ivo.'], [1, 'Hunting?'], [0, 'Circling. All night, round and round.'], [1, 'Like guards.'], [0, "Guarding whatever sits on the saint's throne now."]] },
  { tags: ['hunter'], lines: [[0, 'Venison for the inn tonight, {b}.'], [1, 'At last!'], [0, "Don't ask where I found it."], [1, 'Where did you find it?'], [0, 'Hanging in a tree, dressed and salted. Not by me.']] },
  { tags: ['hunter'], lines: [[0, 'You walk like a cart in a ditch, {b}.'], [1, "I'm being quiet!"], [0, 'The deer in the next valley sat down to laugh.']] },
  { tags: ['hunter'], lines: [[0, 'Shall I teach you to shoot?'], [1, 'Would you?'], [0, 'Rule one: breathe out, then loose.'], [1, 'And rule two?'], [0, "Never shoot at anything that smiles at you. It's not a deer."]] },
  { tags: ['hunter'], lines: [[0, 'The ghasts in the Gloamhollow hunt like wolves.'], [1, 'In packs?'], [0, 'In packs, and they never tire. I ran a mile.'], [1, 'And?'], [0, 'One was still beside me. Breathing on my neck. Patient.']] },
  { tags: ['hunter'], lines: [[0, 'I found the old watch tower in the Darkwood.'], [1, 'Fallen?'], [0, "Down to the cellars. Somebody's still lighting a fire in there."], [1, 'Who?'], [0, "I didn't go down to ask."]] },
  { tags: ['hunter'], lines: [[0, "Wind's wrong for hunting today."], [1, 'From where?'], [0, 'From the graveyard. Every beast in the wood can smell it. So can I.']] },
  { tags: ['hunter'], lines: [[0, 'The rabbits have been at the gravebloom.'], [1, 'Is that bad?'], [0, 'They glow in the dark now. Easy shooting. Bad eating.']] },
  { tags: ['hunter'], lines: [[0, "The dread knights' horses leave no dung."], [1, 'None at all?'], [0, 'Two days I followed them on the Downs. Hoofprints. Nothing else.'], [1, 'What do they eat, then?'], [0, "I'll not follow any closer to find out."]] },
  { tags: ['hunter'], lines: [[0, 'My bowstring was cut while it hung on my wall.'], [1, "Who'd do that?"], [0, 'Someone who knew I meant to go to the Barrow today.'], [1, "Then don't go."], [0, "I'll go tomorrow. With two strings."]] },
  { tags: ['hunter'], lines: [[0, 'I took the stranger hunting.'], [1, 'Any good?'], [0, "Hopeless with a bow. Couldn't hit a barn."], [1, 'Oh dear.'], [0, 'Then a boar charged us. They hit it with the barn door.']] },
  { tags: ['hunter'], lines: [[0, "There's a stag in the Darkwood with a crown of candles."], [1, 'Lit?'], [0, 'Lit. It walks the old procession road at night.'], [1, 'Going where?'], [0, 'The Barrow. Same as everything in that wood.']] },
  { tags: ['hunter'], lines: [[0, 'Joan says my hides have too many holes.'], [1, 'Arrow holes?'], [0, "Most of them. Some are teeth. I'm not saying whose."]] },
  { tags: ['hunter'], lines: [[0, 'The foxes have dug in under the crater.'], [1, 'Warm ground.'], [0, 'They come out with green eyes now.'], [1, 'Is that bad?'], [0, "It's pretty. I don't trust pretty."]] },
  { tags: ['hunter'], lines: [[0, "Know what's quieter than a hunter?"], [1, 'What?'], [0, "Anything that's been dead a week."], [1, 'Saints.'], [0, "You only hear them once they've got your sleeve."]] },
  { tags: ['hunter'], lines: [[0, 'I can track anything, {b}.'], [1, 'Anything?'], [0, 'Except the Sworn. They walk the road and leave nothing on it.'], [1, 'As if the road were theirs.'], [0, 'It is, for now.']] },
  { tags: ['hunter'], lines: [[0, 'Ever eaten troll?'], [1, 'Have you?'], [0, 'Grandfather did. Says it tastes of bog.'], [1, 'What does bog taste of?'], [0, 'Troll.']] },
  { tags: ['hunter'], lines: [[0, 'Something took my best dog in the Darkwood.'], [1, "I'm sorry."], [0, 'It brought him back the next night.'], [1, 'Alive?'], [0, "He wags. He won't eat. He sits by the door, looking out."]] },
  { tags: ['hunter'], lines: [[0, "The Bellwood Trail's gone wild."], [1, 'Nobody walks it now.'], [0, 'Somebody does. Branches are broken nine feet up.'], [1, 'Trolls?'], [0, "Or knights on tall horses. Don't walk it after dark."]] },
  { tags: ['hunter'], lines: [[0, 'Keep this raven feather in your hat, {b}.'], [1, 'What for?'], [0, "They'll take you for one of theirs."], [1, 'Who will?'], [0, "The ravens. They decide who's supper round here."]] },
  { tags: ['hunter'], lines: [[0, "I sleep in the trees when I'm out."], [1, 'Comfortable?'], [0, 'No. Safe. The dead are poor climbers.'], [1, 'And the ghasts?'], [0, 'Good climbers. So I sleep lightly.']] },
  { tags: ['hunter'], lines: [[0, "What's the best bait for wolves?"], [1, 'Meat?'], [0, 'Fear. They smell it a mile off.'], [1, 'So what do you bring?'], [0, 'A merchant. Works every time.']] },
  { tags: ['hunter'], lines: [[0, 'I found a new spring in the Darkwood.'], [1, 'Good water?'], [0, 'Clear as glass. Not a fish in it. Not a fly near it.'], [1, "Then don't drink it."], [0, "I didn't. My horse did. He's been very quiet since."]] },
  { tags: ['hunter'], lines: [[0, 'The deer came back to the woods, {b}.'], [1, 'Good news at last!'], [0, 'Three. They stood at the edge and stared at the crater.'], [1, 'Not grazing?'], [0, 'Praying, maybe. Who am I to shoot a deer at prayer?']] },
  { tags: ['hunter', 'trio'], lines: [[0, 'Quiet, both of you.'], [1, 'What is it?'], [2, "I can't see anything."], [0, "That's it. Nothing in the trees. Nothing in the grass."], [1, 'Is that bad?'], [0, "Everything's hiding. Walk home now. Don't run."]] },
  // -------------------------------------------------------- the gentry
  { tags: ['gentry'], lines: [[0, 'My forebears lie in the Hall of the Founders.'], [1, 'Under the cathedral, {a}?'], [0, "In the great tomb. My name's already carved on the bottom step."], [1, 'Already!'], [0, "They leave room for the family. It's thoughtful, and horrible."]] },
  { tags: ['gentry'], lines: [[0, 'I shall have a curfew posted.'], [1, "There's always been a curfew."], [0, 'Now it will be written down.'], [1, 'Will the dead read it?'], [0, "I suspect they'll be the only ones who keep it."]] },
  { tags: ['gentry'], lines: [[0, 'The garrison has taken the town hall stables.'], [1, 'For their horses?'], [0, 'For their "guests."'], [1, 'What guests?'], [0, "I'm told not to ask. I govern this town, and I am told not to ask."]] },
  { tags: ['gentry'], lines: [[0, 'Fetch me the town charter, {b}.'], [1, 'What for?'], [0, 'To see if it says anything about the dead rising.'], [1, 'Does it?'], [0, 'Under "Sundry Matters." In a very small hand.']] },
  { tags: ['gentry'], lines: [[0, 'We ought to reward the stranger.'], [1, 'With what, {a}?'], [0, 'The freedom of the town.'], [1, 'What comes with that?'], [0, 'A scroll. And our permission to keep doing it.']] },
  { tags: ['gentry'], lines: [[0, 'A petition, {b}?'], [1, 'To have the well blessed again.'], [0, 'How many names?'], [1, 'Forty.'], [0, "There aren't forty grown folk in Bellmourn."], [1, 'The yard signed too.']] },
  { tags: ['gentry'], lines: [[0, 'The bishop has written back at last.'], [1, 'After six years!'], [0, 'He asks if we are all still alive.'], [1, 'What will you answer?'], [0, '"Mostly." And I shall ask him for money.']] },
  { tags: ['gentry'], lines: [[0, 'One must keep up appearances, {b}.'], [1, 'With the dead in the yard?'], [0, 'Especially then. They are watching what we let go.']] },
  { tags: ['gentry'], lines: [[0, "My father took me down to the Ringers' Crypt as a child."], [1, 'Why, {a}?'], [0, 'To show me where the family pays its debts.'], [1, 'What debts?'], [0, 'He never said. He only made me bow to the ringers.']] },
  { tags: ['gentry'], lines: [[0, 'How many households paid the tithe?'], [1, 'All but four.'], [0, 'Which four?'], [1, 'The four that have stood empty since spring.'], [0, "Mark them paid. I'll not have the Sworn knocking at dead doors."]] },
  { tags: ['gentry'], lines: [[0, 'Do you know why our bell has no name?'], [1, "It's called the bell."], [0, 'Every bell is christened. Ours was. Then they chiselled the name off.'], [1, 'Why?'], [0, 'So it would stop answering to it.']] },
  { tags: ['gentry'], lines: [[0, 'Lord Velscour expects a gift at midwinter.'], [1, 'What sort of gift?'], [0, 'Last year a cart of grain. The year before, the miller.'], [1, 'The miller?'], [0, 'He went to deliver the grain. He is still delivering it.']] },
  { tags: ['gentry'], lines: [[0, 'Mind your manners before the Sworn.'], [1, 'They have none.'], [0, 'Then we must have twice as many. Ours and theirs.']] },
  { tags: ['gentry'], lines: [[0, 'I dined alone again.'], [1, 'Lonely, {a}?'], [0, 'I lay places for the old council.'], [1, "They're dead."], [0, 'They still argue. I prefer it to the quiet.']] },
  { tags: ['gentry'], lines: [[0, 'Someone has painted a green star on the town hall door.'], [1, 'Shall I scrub it off?'], [0, 'Before the garrison sees it.'], [1, 'Yes, {a}.'], [0, 'And then paint it again. On the inside.']] },
  { tags: ['gentry'], lines: [[0, 'Do I look tired, {b}?'], [1, 'Not at all, {a}.'], [0, "Liar. Kind liar. Keep lying. It's the last kindness in the town hall."]] },
  { tags: ['gentry'], lines: [[0, 'Whoever governs here must know every soul in the town.'], [1, 'And do you, {a}?'], [0, "Living and dead. The dead are easier. They don't move house."], [1, 'Lately they do.']] },
  { tags: ['gentry'], lines: [[0, "The cathedral roof is the town's to mend."], [1, "Who'll go up?"], [0, "Whoever is behind on their rent. It's an old custom."], [1, 'Since when?'], [0, 'Since this morning.']] },
  { tags: ['gentry'], lines: [[0, 'What would you do, {b}, if you ran Bellmourn?'], [1, 'Leave it.'], [0, "You can't leave. You run it."], [1, "Then I'd ring the bell once, myself. To say goodbye."]] },
  { tags: ['gentry'], lines: [[0, "I've written our troubles in the town book."], [1, 'All of them?'], [0, "The book is full. I've started on the walls."]] },
  { tags: ['gentry'], lines: [[0, 'My grandfather met Lord Velscour once.'], [1, 'What was he like?'], [0, 'Charming, Grandfather said. Very charming.'], [1, 'And?'], [0, 'He never smiled again. "Charming," he\'d say, and shudder.']] },
  { tags: ['gentry'], lines: [[0, 'The Hall of the Founders was bright, in the old days.'], [1, 'Lit with lamps?'], [0, "Braziers at the four corners. Kept by the founders' wives."], [1, 'And now?'], [0, "The stranger says they're still burning. Who keeps them, I'd like to know."]] },
  { tags: ['gentry'], lines: [[0, 'We shall have a feast when this is over.'], [1, 'What will we eat?'], [0, "Whatever's left."], [1, "And who'll come?"], [0, "Whoever's left to eat it."]] },
  { tags: ['gentry'], lines: [[0, "There's a man at the gate who says he owns the inn."], [1, 'Tobias owns the inn.'], [0, "He has a deed two hundred years old. In a founder's hand."], [1, 'And the man?'], [0, 'He looks very like the founder. Very like.']] },
  { tags: ['gentry'], lines: [[0, 'I have decided to be brave.'], [1, 'How, {a}?'], [0, "I'll walk to the cathedral steps at dusk."], [1, "That's very brave."], [0, 'With you. And two lamps. And the sergeant.']] },
  { tags: ['gentry'], lines: [[0, 'Should the town pay the stranger?'], [1, 'For what they do below?'], [0, "For what the rest of us can't."], [1, 'With what coin?'], [0, "The founders' gold, if they bring it up. Fair, and very convenient."]] },
  { tags: ['gentry'], lines: [[0, 'They hanged another man at the crossroads.'], [1, 'The Sworn did?'], [0, 'For "insolence."'], [1, 'What did he say?'], [0, 'Good morning. To the wrong knight, in the wrong voice.']] },
  { tags: ['gentry', 'trio'], lines: [[0, 'Order! Order, the pair of you!'], [1, 'She started it, {a}.'], [2, 'He moved the boundary stone!'], [0, 'Who moved it?'], [1, 'Not me.'], [2, 'Not me.'], [0, 'Then the stone is walking again. Home, both of you.']] },
  // ---------------------------------------------------- the travellers
  { tags: ['traveller'], lines: [[0, 'I came to Bellmourn for a week.'], [1, 'How long ago?'], [0, 'A year this spring.'], [1, 'What kept you?'], [0, 'Every morning I pack. Every evening I unpack. My bags have opinions.']] },
  { tags: ['traveller'], lines: [[0, 'Where I come from we hang bells on the goats.'], [1, 'Why?'], [0, 'To hear them wander.'], [1, "Here we'd never hang a bell on anything we loved."]] },
  { tags: ['traveller'], lines: [[0, "I've drawn the Gloamhollow from a trapper's telling."], [1, 'Is it right?'], [0, "It's beautiful."], [1, 'But is it right?'], [0, 'The cave will say, when someone takes it in.']] },
  { tags: ['traveller'], lines: [[0, 'I fought in a war once, {b}.'], [1, 'Which war?'], [0, "It doesn't matter. All its dead stayed down."], [1, 'Lucky.'], [0, 'I thought so then. Now I think it was manners.']] },
  { tags: ['traveller'], lines: [[0, "What's this inn called again?"], [1, 'The Tolling Bell.'], [0, 'Is everything here named for that bell?'], [1, 'What else would we name things for?'], [0, 'The weather. The cheese. Anything cheerful.']] },
  { tags: ['traveller'], lines: [[0, 'I met a man on the Vigil Road with no shadow.'], [1, 'One of the Sworn?'], [0, 'A pilgrim. Walking to the Keep to beg.'], [1, 'Beg what?'], [0, "To be let in. He'd heard it was warm inside."]] },
  { tags: ['traveller'], lines: [[0, 'Have you any family left, {b}?'], [1, 'A sister at Millhaven.'], [0, 'Write to her.'], [1, 'Why?'], [0, "I never wrote to mine. Don't be me."]] },
  { tags: ['traveller'], lines: [[0, 'Brightwater Falls is the prettiest crossing in the realm.'], [1, 'Is it?'], [0, "If you don't look down into the pool."], [1, "What's in the pool?"], [0, "White shapes, turning slowly. As if they're listening to the water."]] },
  { tags: ['traveller'], lines: [[0, 'I collect a little bell from every town I pass.'], [1, 'How many have you?'], [0, 'Forty.'], [1, 'And one of ours?'], [0, 'Not yours. Not even a small one. It would follow me home.']] },
  { tags: ['traveller'], lines: [[0, "What's the worst danger on the road, {b}?"], [1, 'Wolves? Knights?'], [0, 'Kind folk with a bed to offer.'], [1, 'Why?'], [0, 'You wake in a strange place, owing them more than coin.']] },
  { tags: ['traveller'], lines: [[0, 'I sold my sword in Millhaven, to eat.'], [1, 'And?'], [0, 'Then the dread knights came.'], [1, 'Oh.'], [0, "I wished I'd sold my appetite instead."]] },
  { tags: ['traveller'], lines: [[0, 'They sing of the Mourning Gulf as far as the coast.'], [1, 'What do they sing?'], [0, "That a bridge hangs over it, and no one's crossed it twice."], [1, 'The stranger has.'], [0, 'Then somebody owes the coast a new song.']] },
  { tags: ['traveller'], lines: [[0, 'Why does nobody ever leave this town?'], [1, "We're fond of it."], [0, 'Fond!'], [1, "Fond like a bad tooth. You can't stop touching it."]] },
  { tags: ['traveller'], lines: [[0, "In my country there's a word for this."], [1, 'For what?'], [0, "Homesick for a place you've never been."], [1, "What's the word?"], [0, "I've forgotten it. That's part of the feeling."]] },
  { tags: ['traveller'], lines: [[0, "Someone's been following me on the Bellwood Trail."], [1, 'A bandit?'], [0, 'Seven paces behind. Stops when I stop.'], [1, 'Did you turn round?'], [0, "Not yet. I'm saving it for when I'm sure I want to know."]] },
  { tags: ['traveller'], lines: [[0, 'I came all this way to see your cathedral.'], [1, 'Older than the town.'], [0, 'How can that be?'], [1, "The town grew round it. Like moss round a stone that won't move."]] },
  { tags: ['traveller'], lines: [[0, "I'm a pilgrim, {b}."], [1, 'To the cathedral?'], [0, "To the crater. Six days' walk to see a hole."], [1, 'Was it worth it?'], [0, "I fell in. I'm counting that as blessed."]] },
  { tags: ['traveller'], lines: [[0, 'The Sworn went through my pack at the gate.'], [1, 'Find anything?'], [0, 'A psalter. They tore out the last page.'], [1, 'Why that one?'], [0, "It mentions a green star. I hadn't known till they tore it."]] },
  { tags: ['traveller'], lines: [[0, 'How do I get to Blackvigil from here?'], [1, 'Why would you want to?'], [0, 'I have a letter to deliver.'], [1, 'To whom?'], [0, 'It only says "Blackvigil." Sealed in black wax. It\'s heavier every day.']] },
  { tags: ['traveller'], lines: [[0, "I miss my mother's kitchen."], [1, 'Did she cook well?'], [0, 'Terribly. But it was warm, and nothing scratched at the windows.']] },
  { tags: ['traveller'], lines: [[0, "Who's this hero everyone talks of?"], [1, 'The stranger. They go down under the cathedral.'], [0, 'For coin?'], [1, 'For us, I think.'], [0, "Then they're a fool. I'd like to meet a fool like that."]] },
  { tags: ['traveller'], lines: [[0, "I've walked five hundred miles in these boots."], [1, 'Where next?'], [0, 'Down, I think. Under the cathedral.'], [1, "You'll die."], [0, "Then I'll have walked five hundred miles to die somewhere interesting."]] },
  { tags: ['traveller'], lines: [[0, 'I can tell a town by its dogs.'], [1, 'And ours?'], [0, "They don't bark. They listen with their noses to the ground."], [1, 'Toward the cathedral.'], [0, 'Toward everything. Your dogs think the ground is lying to them.']] },
  { tags: ['traveller'], lines: [[0, "I'm writing a book of my travels."], [1, 'Will Bellmourn be in it?'], [0, 'One chapter.'], [1, 'Only one?'], [0, 'A short one. If I put it all in, nobody would believe the rest.']] },
  { tags: ['traveller'], lines: [[0, 'I met one of the Sworn on the road, weeping.'], [1, 'Weeping?'], [0, 'Inside his helm. I heard it. He told me to walk on.'], [1, 'Did you?'], [0, 'I did. I left my last apple on a stone beside him.']] },
  { tags: ['traveller'], lines: [[0, "The southern caravans won't come here any more."], [1, 'Because of the dead?'], [0, "Because of the tithe. The dead, they'd pay to see."]] },
  { tags: ['traveller', 'trio'], lines: [[0, 'Three of us came over the hill together.'], [1, 'Strangers, then.'], [2, 'Strangers still.'], [0, 'One goes on to the Keep.'], [1, 'One goes down the stair.'], [2, 'And one stays at the inn till spring.'], [0, "That's the clever one."]] },
  // ----------------------------------------------------------- the old
  { tags: ['old'], lines: [[0, 'My grandmother remembered Abbot Cindermaw.'], [1, "She can't have. He's centuries dead."], [0, "She told it as if she'd been there. Hot hands, she said."], [1, 'Hot hands?'], [0, 'He blessed her in her cradle. She had the marks all her life.']] },
  { tags: ['old'], lines: [[0, 'When I was young the Gulf had no bridge.'], [1, 'How did they cross?'], [0, "They didn't. Then the sexton built one."], [1, 'Why?'], [0, 'He said someone on the far side kept asking him to.']] },
  { tags: ['old'], lines: [[0, 'I was here for the last plague.'], [1, 'The one they walled up?'], [0, 'I carried bones down to the ossuary myself. Ten years old.'], [1, 'Saints.'], [0, "They were light. That's what I remember. How light they were."]] },
  { tags: ['old'], lines: [[0, "The young don't know how to grieve."], [1, 'How should we?'], [0, 'Loud, and once. Then get on with it.'], [1, 'And instead?'], [0, 'Quiet and forever. Like this whole town.']] },
  { tags: ['old'], lines: [[0, "I can smell when someone's going to die."], [1, 'What does it smell like?'], [0, 'Apples. Old ones.'], [1, '...I had an apple this morning.'], [0, 'That was just an apple, dear. Have another and see.']] },
  { tags: ['old'], lines: [[0, 'Did I ever tell you where I did my courting?'], [1, 'At the well.'], [0, 'In the graveyard. We were both burying someone.'], [1, 'Romantic.'], [0, 'It was. We buried them together. Went quicker.']] },
  { tags: ['old'], lines: [[0, 'In my day the Vigil kept the roads.'], [1, 'The Sworn? Those ones?'], [0, 'Good men, once. Our own sons.'], [1, 'What happened to them?'], [0, 'Something at Blackvigil sang to them. They all went in to listen.']] },
  { tags: ['old'], lines: [[0, "I've a chest of letters I never sent."], [1, 'To whom?'], [0, "Everyone I've buried. One each."], [1, 'Will you send them?'], [0, "I'll take them with me. Save on the carrier."]] },
  { tags: ['old'], lines: [[0, 'You young folk walk so fast.'], [1, "We've places to be."], [0, "So have I. I'm only not in a hurry to get there."]] },
  { tags: ['old'], lines: [[0, 'We courted at the waterfall when I was young.'], [1, 'At Brightwater?'], [0, "Before the drowned folk came. You'd lean over the pool and kiss."], [1, 'And now?'], [0, "Now you'd lean over, and something would kiss you back."]] },
  { tags: ['old'], lines: [[0, "I knew Saint Ivo's great-grandniece."], [1, 'Was she holy?'], [0, 'She cheated at cards. Holiness skips a generation, she said.'], [1, 'Only one?'], [0, 'Sometimes six.']] },
  { tags: ['old'], lines: [[0, 'How old do you think I am, {b}?'], [1, 'Seventy?'], [0, 'Kind.'], [1, 'Eighty?'], [0, 'Kinder.'], [1, 'Ninety?'], [0, "Now you're just being cruel. Eighty-one."]] },
  { tags: ['old'], lines: [[0, "My mother hid from Velscour's first riders in the bread oven."], [1, 'Was it lit?'], [0, 'It was warm.'], [1, 'And?'], [0, 'She came out half-baked, she said. And alive.']] },
  { tags: ['old'], lines: [[0, "We had a dance on Founders' Day."], [1, 'Do you miss it?'], [0, 'I miss my feet. They were very good at it.']] },
  { tags: ['old'], lines: [[0, 'Everyone I knew is in the yard now.'], [1, 'Not everyone. You know me.'], [0, "You're a child."], [1, "I'm forty!"], [0, 'A child. Wait till you know more of them below than above.']] },
  { tags: ['old'], lines: [[0, 'The founders came over the downs with nothing but a bell.'], [1, 'Why a bell?'], [0, 'To call the town together.'], [1, 'And did it?'], [0, "It did. And it's never once let us go since."]] },
  { tags: ['old'], lines: [[0, 'Fetch my shawl, {b}.'], [1, "It's warm today."], [0, 'Warm for you. For me, the yard is breathing down my neck.']] },
  { tags: ['old'], lines: [[0, "I've chosen my stone."], [1, 'In the yard?'], [0, 'Plain. With a lid that bolts from the inside.'], [1, 'The inside?'], [0, "I'll decide for myself when I come and go."]] },
  { tags: ['old'], lines: [[0, 'We were wed on the cathedral steps.'], [1, 'How lovely.'], [0, 'The bell rang just as the vows were asked.'], [1, 'A sign!'], [0, 'We both said yes. Neither heard the other. We wondered ever after.']] },
  { tags: ['old'], lines: [[0, "I'm teaching my grandson the old prayers."], [1, 'For the dead?'], [0, 'For the living. The dead have heard them all. They get bored.']] },
  { tags: ['old'], lines: [[0, "My mother's in the floor of the Gallery of the Poor."], [1, 'Under the cathedral?'], [0, "We couldn't afford a stone. I pressed my thumb into the clay over her."], [1, 'Is it still there?'], [0, "The stranger says it's been pressed back. From underneath."]] },
  { tags: ['old'], lines: [[0, "Do you know what's worse than dying, {b}?"], [1, 'What?'], [0, 'Waiting.'], [1, 'And worse than waiting?'], [0, "Waiting beside someone who won't stop talking about it."]] },
  { tags: ['old'], lines: [[0, 'In my day a girl could walk to Millhaven alone.'], [1, 'Truly?'], [0, 'Barefoot, with a basket of eggs, singing.'], [1, 'And now?'], [0, "Now even the eggs won't go."]] },
  { tags: ['old'], lines: [[0, "I've buried a brother, two cousins and a goat."], [1, "I'm sorry."], [0, 'The goat was the worst. The others had been ill for years.']] },
  { tags: ['old'], lines: [[0, 'The old watch rang a little handbell at curfew.'], [1, 'Not the great bell?'], [0, 'Never the great bell. Only fools rang that.'], [1, 'And who rings it now?'], [0, "Fools. Or nobody. I can't say which is worse."]] },
  { tags: ['old'], lines: [[0, 'I wish I were young enough to go down with the stranger.'], [1, 'Down the stair?'], [0, "I'd show them where the ringers hid their good relics."], [1, 'How would you know where?'], [0, 'I was young once, {b}. And very curious.']] },
  { tags: ['old'], lines: [[0, 'Speak up, {b}.'], [1, "I said it's a fine day."], [0, 'I heard you. I wanted to hear it twice.']] },
  { tags: ['old'], lines: [[0, "My memory's going."], [1, 'What did you have for breakfast?'], [0, "I couldn't tell you. But I remember the night they walled up the plague."], [1, "That's how it goes."], [0, 'The bad stays. The bread slips through.']] },
  { tags: ['old', 'trio'], lines: [[0, 'Three old fools on a bench.'], [1, 'Speak for yourself.'], [2, "I'm not old. I'm seasoned."], [0, 'Like a ham, {c}.'], [2, 'Like a very fine ham.'], [1, 'Hang us in the chimney, then, and have done.']] },
  // --------------------------------------------------------- the young
  { tags: ['young'], lines: [[0, "I'm going to be the stranger's squire."], [1, 'Do they want a squire?'], [0, 'They will when they see how much I can carry.'], [1, 'How much can you carry?'], [0, 'Two buckets and a grudge.']] },
  { tags: ['young'], lines: [[0, 'Dare you to say good morning to one of the black knights.'], [1, "You're mad."], [0, 'Just "good morning."'], [1, 'You do it, then.'], [0, "...I'll dare you again tomorrow."]] },
  { tags: ['young'], lines: [[0, 'I saw the stranger fight a ghast in the yard!'], [1, 'You were out after dark?'], [0, 'I dreamt it. A very clear dream. From the hayloft.']] },
  { tags: ['young'], lines: [[0, "Mother says I can't go to the crater any more."], [1, 'Why not?'], [0, 'I came home glowing.'], [1, 'Glowing!'], [0, 'Only a little. Only in the dark. Only my fingernails.']] },
  { tags: ['young'], lines: [[0, 'Want to play Sworn and Flame?'], [1, "Who's the Flame?"], [0, 'You. You jump off the wall onto me.'], [1, "That'll hurt."], [0, "It's supposed to. It's history."]] },
  { tags: ['young'], lines: [[0, 'Somebody left a flower on my windowsill.'], [1, 'What kind?'], [0, 'Gravebloom. Still glowing.'], [1, 'From the graves?'], [0, "Somebody braved the yard for me. I'm not sure if that's sweet."]] },
  { tags: ['young'], lines: [[0, 'I went down three steps of the cathedral stair.'], [1, 'Three!'], [0, 'Four. The fourth was warm.'], [1, 'Warm how?'], [0, 'As if someone had sat on it a long while, waiting.']] },
  { tags: ['young'], lines: [[0, "When I'm grown I'll ride to the Keep and fight the Red Hand."], [1, 'Ser Malgrave?'], [0, "I'll cut his hand off."], [1, 'And then what will they call him?'], [0, 'The Red Stump.']] },
  { tags: ['young'], lines: [[0, "I've been practising with a sword."], [1, 'What sword?'], [0, 'A broom.'], [1, 'Any good?'], [0, "The broom's terrified of me."]] },
  { tags: ['young'], lines: [[0, 'Keep watch while I sneak out?'], [1, 'Where to?'], [0, 'The crater. They say a wish made there at midnight comes true.'], [1, 'What will you wish?'], [0, 'Not to get caught sneaking out.']] },
  { tags: ['young'], lines: [[0, "I'm not scared of the graveyard."], [1, 'Go on, then. Walk through it.'], [0, "I'm not scared of it from here, I mean."]] },
  { tags: ['young'], lines: [[0, 'Have you ever kissed anyone, {b}?'], [1, "That's none of your business."], [0, 'So, no.'], [1, 'So, not telling.']] },
  { tags: ['young'], lines: [[0, 'I want to leave Bellmourn and see the sea.'], [1, "What's the sea?"], [0, "Water that doesn't end."], [1, 'Like the Gulf?'], [0, 'The other way. Sideways, and full of fish.']] },
  { tags: ['young'], lines: [[0, 'Father made me scrub the doorstep again.'], [1, 'Why?'], [0, 'Chalk marks. Little crosses. One for each of us.'], [1, 'Who drew them?'], [0, 'Something that knows how to count our family.']] },
  { tags: ['young'], lines: [[0, 'The stranger taught me a card trick.'], [1, 'Show me!'], [0, 'Pick a card.'], [1, 'This one.'], [0, "Now it's gone."], [1, 'Where?'], [0, "I don't know. That's as far as they'd got when they left for the crypts."]] },
  { tags: ['young'], lines: [[0, "My cousin says ghasts can't see you if you hold your breath."], [1, 'Is it true?'], [0, 'He held his breath in the Darkwood for a whole minute.'], [1, 'And?'], [0, 'It saw him. But it was very impressed.']] },
  { tags: ['young'], lines: [[0, "I'm going to marry the stranger."], [1, 'Have you asked?'], [0, "Not yet. I'll wait till they've killed the Fiend."], [1, 'Why wait?'], [0, "They'll have more time for me after."]] },
  { tags: ['young'], lines: [[0, 'Do you know the game called Bell?'], [1, 'How do you play?'], [0, 'Everyone hides. One person rings.'], [1, 'And?'], [0, "Whoever's still hiding when it stops has to stay hidden for ever."], [1, "That's horrible."], [0, "It's very hard to win."]] },
  { tags: ['young'], lines: [[0, "Why can't children go near the cathedral?"], [1, 'Because of the dead.'], [0, 'The dead were children too, once.'], [1, "That's exactly why."]] },
  { tags: ['young'], lines: [[0, 'I helped the stranger find their sword.'], [1, 'Where was it?'], [0, 'In the stables, under a hat.'], [1, 'Whose hat?'], [0, 'Nobody would own up to the hat.']] },
  { tags: ['young'], lines: [[0, 'My big brother joined the Sworn.'], [1, 'He never!'], [0, 'He came home for my birthday. He kept his helm on.'], [1, 'Was it really him?'], [0, "He knew my name. He didn't know my birthday."]] },
  { tags: ['young'], lines: [[0, "I'm the fastest runner in Bellmourn."], [1, 'Says who?'], [0, "Says everything that's ever chased me. They're still behind."]] },
  { tags: ['young'], lines: [[0, "Let's go and watch the black knights drill."], [1, 'Why?'], [0, 'To learn how they fight. For when we fight them.'], [1, "They'll see us."], [0, "We'll be very small and very behind a wall."]] },
  { tags: ['young'], lines: [[0, 'Grown-ups never tell us anything.'], [1, 'Like what?'], [0, "Like what's at the bottom of the stair."], [1, "They don't know either."], [0, 'Then why do they whisper it?']] },
  { tags: ['young'], lines: [[0, "I'm bored, {b}."], [1, 'Bored is lucky, here.'], [0, "Then I'm the luckiest one in Bellmourn and I hate it."]] },
  { tags: ['young'], lines: [[0, 'Do the dead have birthdays?'], [1, 'What a question.'], [0, 'Do they?'], [1, 'They must have had them once.'], [0, "Then let's make them a cake. They might stay down if they're happy."]] },
  { tags: ['young'], lines: [[0, "I've saved four coppers."], [1, 'For what?'], [0, 'To buy the stranger a sword.'], [1, "Four coppers won't buy a sword."], [0, "It'll buy a very small one. For the very small dead."]] },
  { tags: ['young', 'trio'], lines: [[0, 'Swear it.'], [1, 'I swear.'], [2, 'I swear.'], [0, 'Nobody tells Mother we went to the crater.'], [1, 'Nobody.'], [2, 'Not even if she asks.'], [0, 'Especially not if she asks about my eyebrows.']] },
  // -------------------------------------------------------- the farmer
  { tags: ['farmer'], lines: [[0, 'Ploughed up a helmet in the north field.'], [1, 'An old one?'], [0, 'Old enough to have a head still in it.'], [1, 'Saints. And then?'], [0, "Ploughed round it. He's earned the spot."]] },
  { tags: ['farmer'], lines: [[0, 'The dread knights rode through my wheat.'], [1, 'Much harm done?'], [0, "They rode in a straight line, as if it weren't there."], [1, 'And?'], [0, 'Every stalk lies flat now. Pointing west, to the Keep.']] },
  { tags: ['farmer'], lines: [[0, 'My pumpkins came up with faces.'], [1, 'Carved?'], [0, 'Grown. Every one of them. All frowning at the cathedral.']] },
  { tags: ['farmer'], lines: [[0, "The Millhaven miller won't grind any more."], [1, 'Why not?'], [0, 'He says the stones bring up voices with the flour.'], [1, 'What do they say?'], [0, '"Finer." They always want it finer.']] },
  { tags: ['farmer'], lines: [[0, 'Warm rain, {b}.'], [1, 'Good for the fields.'], [0, 'Warm rain brings the worms up.'], [1, 'Is that bad?'], [0, 'And whatever eats worms. And whatever eats that.']] },
  { tags: ['farmer'], lines: [[0, 'My sheep have taken to sleeping in a ring.'], [1, 'For warmth?'], [0, 'Facing outward. Like soldiers.'], [1, 'Clever sheep.'], [0, "Frightened sheep. It's the same thing, round here."]] },
  { tags: ['farmer'], lines: [[0, 'A calf was born with a white V on its face.'], [1, 'Saints, hide it!'], [0, 'From whom?'], [1, "The garrison. They'll take it."], [0, 'Let them. It kicks.']] },
  { tags: ['farmer'], lines: [[0, "What's grain fetching at market?"], [1, 'Two coppers a sack.'], [0, 'And the tithe?'], [1, 'Three.'], [0, 'So I pay a copper a sack for the joy of growing it.']] },
  { tags: ['farmer'], lines: [[0, "There's a hare sits in my field every evening and watches me."], [1, 'Shoot it.'], [0, "It's my grandmother."], [1, "It's a hare."], [0, 'It has her eyebrows, {b}.']] },
  { tags: ['farmer'], lines: [[0, "I'll plant the bottom field this year."], [1, 'By the yard wall?'], [0, 'The soil there is rich as cake.'], [1, 'I wonder why.'], [0, "I don't. I've learned not to."]] },
  { tags: ['farmer'], lines: [[0, "The horse won't drink from the trough."], [1, 'Sick?'], [0, "There's something in the water, looking up."], [1, 'A frog?'], [0, 'Smaller than a frog. With hands.']] },
  { tags: ['farmer'], lines: [[0, "Hay's in, {b}."], [1, 'Good crop?'], [0, 'Three mice, two adders and a sword in it.'], [1, 'A sword?'], [0, "Old, good steel. I'll trade it to the smith for a new fork."]] },
  { tags: ['farmer'], lines: [[0, "Half of Millhaven's empty now."], [1, 'Fled?'], [0, "To the falls, the woods, anywhere. My brother's holding the farm."], [1, 'Alone?'], [0, "With a pitchfork and a foul temper. He'll be fine."]] },
  { tags: ['farmer'], lines: [[0, 'Nowhere else grows turnips like Bellmourn.'], [1, 'How big?'], [0, "Big as a baby's head."], [1, "What's your secret?"], [0, "We don't talk about what the soil's been fed."]] },
  { tags: ['farmer'], lines: [[0, 'The dread knights bought my apples.'], [1, 'Bought them?'], [0, 'Paid in silver. Every coin with a V.'], [1, 'Will you spend it?'], [0, 'I melted it into a bell for my cow. She hates it.']] },
  { tags: ['farmer'], lines: [[0, 'Crows on the scarecrow again.'], [1, "That's what crows do."], [0, "They're bringing it things. Rings. Buttons. A spoon."], [1, 'Like gifts.'], [0, "Like it's their king."]] },
  { tags: ['farmer'], lines: [[0, 'My pigs got out.'], [1, 'Where to?'], [0, 'The cathedral steps. All twelve, sat in rows like a congregation.'], [1, 'Did you fetch them?'], [0, 'After the sermon. It seemed rude not to let them finish.']] },
  { tags: ['farmer'], lines: [[0, 'I dug a new well.'], [1, 'Good water?'], [0, 'Bitter. And at the bottom, a door.'], [1, 'A door?'], [0, "Oak, with a knocker. I filled it in. I'm not knocking."]] },
  { tags: ['farmer'], lines: [[0, "The milk's turned again."], [1, 'Thunder?'], [0, 'The bell. Every time it rings, the milk turns.'], [1, 'Then drink it before the bell.'], [0, "I've never once been that quick."]] },
  { tags: ['farmer'], lines: [[0, 'How many fields do you work, {b}?'], [1, 'Two.'], [0, 'I work three. One by day, and two by night.'], [1, 'By night?'], [0, 'Somebody does the night work. I only find it done.']] },
  { tags: ['farmer'], lines: [[0, 'No harvest feast this year.'], [1, 'Why ever not?'], [0, 'Last year the yard came to it.'], [1, 'Uninvited?'], [0, 'Invited. That was the trouble. Grandfather asked his whole family.']] },
  { tags: ['farmer'], lines: [[0, "The geese won't fly south this year."], [1, 'Why not?'], [0, 'They tried. Back the same afternoon.'], [1, 'Something turned them?'], [0, "They won't say. They're geese. They'd say if they could."]] },
  { tags: ['farmer'], lines: [[0, 'I lost a ewe on the Downs.'], [1, 'To wolves?'], [0, 'To a sorcerer. He turned her to stone.'], [1, 'Stone!'], [0, 'Prettiest statue on the Downs. Still a loss.']] },
  { tags: ['farmer'], lines: [[0, 'Want to buy a cow?'], [1, "What's wrong with her?"], [0, 'Nothing. Good milk. Quiet.'], [1, 'Then why sell?'], [0, "She stands in the yard at night among the stones, chewing. I'm tired of fetching her."]] },
  { tags: ['farmer'], lines: [[0, "Harvest's in, and the tithe's out."], [1, "What's left?"], [0, 'Enough for us, the pigs, and one good supper.'], [1, "That's not bad."], [0, "Not bad for Bellmourn. Anywhere else they'd riot."]] },
  { tags: ['farmer'], lines: [[0, 'Odd tracks in the barley this morning.'], [1, 'Deer?'], [0, 'Bare feet. Out of the yard, round the field, and back again.'], [1, 'Why?'], [0, "Missed the walk, I suppose. I'd miss it too."]] },
  { tags: ['farmer', 'trio'], lines: [[0, "Who'll help me bring the harvest in?"], [1, 'For what pay?'], [2, 'For what share?'], [0, 'A sack each, and supper.'], [1, 'And ale?'], [0, 'And ale.'], [2, "Then I'm yours till dark. Not a moment after."]] },
  // ----------------------------------------------------------- the inn
  { tags: ['innkeeper'], lines: [[0, 'My brother fished below Brightwater.'], [1, "I know. I'm sorry, {a}."], [0, 'I keep his chair by the fire.'], [1, 'Does anyone sit in it?'], [0, "Nobody dares. It's always damp."]] },
  { tags: ['innkeeper'], lines: [[0, "The stranger's tab is longer than my arm."], [1, 'Will they pay?'], [0, 'They paid with a silver chalice from the crypts.'], [1, "That's worth ten tabs!"], [0, "Ten tabs and a priest's curse. I've hung it behind the bar."]] },
  { tags: ['innkeeper'], lines: [[0, 'The Sworn drink here of an evening.'], [1, 'Through their helms?'], [0, "They lift the visor an inch. I've never seen above a chin."], [1, 'What are the chins like?'], [0, 'Shaved. Every one. Too well. Like a corpse laid out for a wake.']] },
  { tags: ['innkeeper'], lines: [[0, 'The guest in four paid a year ahead.'], [1, 'Generous.'], [0, "He's never left the room. I hear him pacing."], [1, 'Does he eat?'], [0, 'He eats the candles. I stopped sending them. Now he paces in the dark.']] },
  { tags: ['innkeeper'], lines: [[0, 'We had a brawl last night.'], [1, 'Over what?'], [0, 'Two men told the same ghost story and fought over the ending.'], [1, 'Who won?'], [0, 'The ghost. It turned up to settle it.']] },
  { tags: ['innkeeper'], lines: [[0, 'The Sworn take a cask a week, for the Vigil.'], [1, 'Do you charge them?'], [0, 'I charge the reeve. The reeve charges you.'], [1, 'And who charges the Sworn?'], [0, 'Somebody will, one day. With a sword, I hope.']] },
  { tags: ['innkeeper'], lines: [[0, 'I keep a cudgel under the bar.'], [1, 'For drunks?'], [0, 'For whatever comes up out of the cellar. Drunks I just ask nicely.']] },
  { tags: ['innkeeper'], lines: [[0, 'Want to hear the best story ever told in this inn?'], [1, 'Go on.'], [0, 'A man drank thirteen ales, went down the cathedral stair and came up sober.'], [1, 'What did he see?'], [0, 'He never drank again. Saddest thing I ever heard.']] },
  { tags: ['innkeeper'], lines: [[0, 'The stranger sleeps in their boots.'], [1, 'How do you know?'], [0, 'Crypt mud on the sheets, every morning.'], [1, 'Charge them for the washing.'], [0, "I did. They paid in ghast teeth. I've a jar of them now."]] },
  { tags: ['innkeeper'], lines: [[0, "Room three's door opens by itself at midnight."], [1, 'Lock it.'], [0, "It's locked. It opens anyway, and shuts again, polite as you like."], [1, 'What goes in?'], [0, "Nothing I can see. But the bed's warm in the morning."]] },
  { tags: ['innkeeper'], lines: [[0, 'Sing us something, {b}.'], [1, 'Here?'], [0, "The fiddler's gone quiet for once. Somebody has to."], [1, 'I only know the one.'], [0, "Then sing it twice. They'll be drunk enough by the second."]] },
  { tags: ['innkeeper'], lines: [[0, "This inn's named for my great-grandfather."], [1, 'He was called Tolling Bell?'], [0, 'He was the last man to ring that bell by hand.'], [1, 'What happened?'], [0, 'He poured ale for forty years after, trying to forget the sound.']] },
  { tags: ['innkeeper'], lines: [[0, 'A woman came in, had soup, and left a ring to pay.'], [1, 'Gold?'], [0, 'Old gold, with the bell on it.'], [1, 'And the woman?'], [0, 'Never came back. I found the bowl in the yard. Still warm.']] },
  { tags: ['innkeeper'], lines: [[0, "Cellar's flooded again."], [1, 'Rain?'], [0, "It's coming up from underneath. Warm, and smelling of incense."], [1, 'From the cathedral?'], [0, 'Everything in this town comes from the cathedral in the end.']] },
  { tags: ['innkeeper'], lines: [[0, 'Who sits by the hearth all evening and never orders?'], [1, 'Old men.'], [0, 'Old men order. This one only warms his hands.'], [1, 'And?'], [0, "They're grey right through, {b}. The fire shows through them."]] },
  { tags: ['innkeeper'], lines: [[0, "Ale's on the house tonight!"], [1, 'Why?'], [0, 'The stranger came back up from the crypts.'], [1, 'Again?'], [0, "Every time they come back, it's on the house. I'm going broke on hope."]] },
  { tags: ['innkeeper'], lines: [[0, 'Somebody carved a V into my best table.'], [1, 'One of the Sworn?'], [0, 'With a dagger, while he ordered. Then he tipped me.'], [1, 'Generously?'], [0, "Enough for a new table. That's what frightened me."]] },
  { tags: ['innkeeper'], lines: [[0, "I've put up rules for the inn."], [1, 'What rules?'], [0, "No swords on the table. No spells in the stew. No saying the burning abbot's name."], [1, 'Why not that?'], [0, 'The hearth goes up like a bonfire every time.']] },
  { tags: ['innkeeper'], lines: [[0, "Today's stew is rabbit."], [1, 'Is it?'], [0, "It's rabbit-shaped. That's close enough, in Bellmourn."]] },
  { tags: ['innkeeper'], lines: [[0, "A man sold me a cask of wine from the founders' tomb."], [1, 'Is it any good?'], [0, 'Three hundred years old.'], [1, 'And?'], [0, 'It tastes of dust and very old grudges.']] },
  { tags: ['innkeeper'], lines: [[0, "I've not slept a full night since the comet."], [1, 'Busy?'], [0, 'Pilgrims in every bed, on every floor, in the stable.'], [1, 'Good for trade.'], [0, "Hard on the back. One's asleep in the bread bin."]] },
  { tags: ['innkeeper'], lines: [[0, "You've had enough, {b}."], [1, 'One more.'], [0, 'You said that three ago.'], [1, 'And I was right then, too.'], [0, 'Home. Mind the yard. Go the long way round.']] },
  { tags: ['innkeeper'], lines: [[0, 'One of the Sworn bought a round for the whole inn.'], [1, 'Kind of him.'], [0, 'Then he wrote down the name of everyone who drank it.']] },
  { tags: ['innkeeper'], lines: [[0, 'Do you know what an innkeeper hears, {b}?'], [1, 'Everything.'], [0, 'Everything. And what does he say?'], [1, 'Nothing.'], [0, 'Good. Now, what have you heard about the reeve?']] },
  { tags: ['innkeeper'], lines: [[0, 'I put the stranger in the best room.'], [1, "You've a best room?"], [0, 'The one where the roof leaks least and nothing has died.'], [1, 'Ever?'], [0, 'Recently.']] },
  { tags: ['innkeeper'], lines: [[0, "The fire's gone out three times tonight."], [1, 'The chimney?'], [0, "Something's sat up it, dropping soot and giggling."], [1, 'Giggling?'], [0, "Like a child up a tree. I've left it a biscuit."]] },
  { tags: ['innkeeper'], lines: [[0, "What'll it be, {b}?"], [1, 'Something strong.'], [0, 'Bad day?'], [1, 'A funeral.'], [0, "Then it's on the house, and I'll sit with you a while."]] },
  { tags: ['innkeeper', 'trio'], lines: [[0, 'Last orders!'], [1, 'One more!'], [2, 'Two more!'], [0, "You can't each have more than the other."], [1, 'Three, then.'], [2, 'Four.'], [0, 'Out, the pair of you. Mind the yard.']] },
  // ------------------------------------------------------- the learned
  { tags: ['learned'], lines: [[0, 'I lowered a lamp into the Mourning Gulf on a line.'], [1, 'How far did it go?'], [0, 'Three hundred feet. Then something took it, and the line went slack.'], [1, 'Did you get the lamp back?'], [0, 'Next morning. On my doorstep. Still lit.']] },
  { tags: ['learned'], lines: [[0, 'I tried to make a fire that never goes out.'], [1, 'And?'], [0, 'It went out. And took my eyebrows with it.'], [1, 'Again?'], [0, "They grow back faster every time. That's a discovery in itself."]] },
  { tags: ['learned'], lines: [[0, 'Glowcaps give light without heat.'], [1, 'Useful.'], [0, 'Bottle it, and no one need buy a candle again.'], [1, "The chandler won't thank you."], [0, "She can sell the dark instead. There's plenty of it."]] },
  { tags: ['learned'], lines: [[0, 'The dead in the Gallery of the Poor move toward warmth.'], [1, 'Like moths?'], [0, 'Like the cold remembering. Bring a brazier and they gather round it.'], [1, 'And if you bring none?'], [0, "Then they gather round you. You're the warmest thing down there."]] },
  { tags: ['learned'], lines: [[0, "I've reckoned when the bell will next ring on its own."], [1, 'When?'], [0, 'Tonight. The third hour.'], [1, "And if it doesn't?"], [0, "Then I've learned something. That's better than being right."]] },
  { tags: ['learned'], lines: [[0, 'Pass me the quicksilver, {b}.'], [1, "This? It's moving."], [0, 'It always moves.'], [1, "It's moving toward the door."], [0, "Then it knows something we don't. Shut the door."]] },
  { tags: ['learned'], lines: [[0, "Ringers' bone dust is the finest there is."], [1, 'Why?'], [0, 'Centuries of the bell shaking it. Fine as flour.'], [1, "What's it good for?"], [0, "It makes the dead sneeze. It's a start."]] },
  { tags: ['learned'], lines: [[0, 'I wrote to the Academy about Bellmourn.'], [1, 'What did they say?'], [0, 'They asked me to stop writing.'], [1, 'Why?'], [0, "My letters arrive smelling of incense. The carriers won't touch them."]] },
  { tags: ['learned'], lines: [[0, 'Is a ghost a thing, {b}, or an event?'], [1, "What's the difference?"], [0, 'A thing stays. An event happens. Ours happen again and again.'], [1, 'So?'], [0, 'So ours are habits. The dead here have very bad habits.']] },
  { tags: ['learned'], lines: [[0, 'Sulphur, saltpetre, charcoal.'], [1, 'What will that make?'], [0, 'A loud noise.'], [1, 'Only that?'], [0, 'A loud noise, aimed down the cathedral stair. The reeve has not agreed.']] },
  { tags: ['learned'], lines: [[0, 'The ghasts see only in the dark.'], [1, 'Then fight them at noon.'], [0, "Tell that to the Gloamhollow. It hasn't seen noon in a thousand years."]] },
  { tags: ['learned'], lines: [[0, "I've been studying the crater glass."], [1, 'And?'], [0, 'It remembers falling.'], [1, 'How can glass remember?'], [0, 'Hold a piece. Your stomach drops every time. Try it.']] },
  { tags: ['learned'], lines: [[0, "What's the opposite of a bell, {b}?"], [1, 'Silence?'], [0, 'A well. One sends sound up. The other swallows it down.'], [1, 'And Bellmourn has both.'], [0, "That's my point. We're a balanced town. Barely."]] },
  { tags: ['learned'], lines: [[0, 'I have a theory about the First Bell, under the cathedral.'], [1, 'Go on.'], [0, "It isn't hung to be rung. It's hung to be heard. Everything below obeys it."], [1, 'Then nobody should ring it.'], [0, "Or the right one should, and call the dead where they're wanted."]] },
  { tags: ['learned'], lines: [[0, 'Tell me what you dreamed last night, {b}.'], [1, 'Why?'], [0, "I keep a book of the town's dreams."], [1, "What's in it?"], [0, 'Water. Bells. Teeth. And now green fire. Everyone. Every night.']] },
  { tags: ['learned'], lines: [[0, 'I put a dead rat in a jar to see if it would rise.'], [1, 'Did it?'], [0, 'It sat up on the third day.'], [1, 'Saints!'], [0, 'Then it sulked. It was still in a jar.']] },
  { tags: ['learned'], lines: [[0, 'Fire needs air, {b}.'], [1, 'Everyone knows that.'], [0, 'Then how does a fire burn three hundred years in a sealed tomb?'], [1, 'The burning abbot?'], [0, "He isn't burning air. He's burning something else. I'd like to know what."]] },
  { tags: ['learned'], lines: [[0, "Hold this. Don't drop it."], [1, 'What is it?'], [0, "If you drop it, we'll both find out."]] },
  { tags: ['learned'], lines: [[0, "The Founders' Tomb is laid out by the stars."], [1, 'Which stars?'], [0, 'The ones over Bellmourn the night it was founded.'], [1, 'And?'], [0, "There's a gap where a green star ought to be. They knew."]] },
  { tags: ['learned'], lines: [[0, 'I distil tears, {b}.'], [1, 'Whose?'], [0, "Anyone's. Grief makes the strongest tincture."], [1, 'What does it do?'], [0, "Stops a heart breaking, for a day. I've sold out."]] },
  { tags: ['learned'], lines: [[0, 'Do you believe in saints, {b}?'], [1, 'Do you?'], [0, 'I believe in what I can weigh.'], [1, 'Can you weigh a saint?'], [0, "The stranger is about eleven stone. It's a start."]] },
  { tags: ['learned'], lines: [[0, 'The Darkwood trees grow in rings round the Barrow.'], [1, 'Planted?'], [0, 'Grown. Leaning out, away from the middle.'], [1, "As if they're afraid?"], [0, "Trees don't fear. They avoid. It's more dignified."]] },
  { tags: ['learned'], lines: [[0, 'A spell is only a recipe, {b}.'], [1, 'Like bread?'], [0, 'Like bread. Flour, water, the wrong word at the right time.'], [1, 'And if you get it wrong?'], [0, 'Then the bread eats you.']] },
  { tags: ['learned'], lines: [[0, "My cat won't come in since the comet."], [1, 'Frightened?'], [0, 'Offended. Something brighter than her arrived. She hates competition.']] },
  { tags: ['learned'], lines: [[0, "You can tell how long someone's been dead by their eyes."], [1, 'How?'], [0, 'Milk at a week. Grey at a year. Green at a century.'], [1, 'And the ones in our yard?'], [0, "Every colour. Somebody's been busy for a very long time."]] },
  { tags: ['learned'], lines: [[0, "I measured the bell's toll with a bowl of water."], [1, 'How?'], [0, 'The ripples. You watch which way they run.'], [1, 'And?'], [0, 'They ran the wrong way. Toward the bell.']] },
  { tags: ['learned'], lines: [[0, 'Every book in the cathedral library is a copy.'], [1, 'Of what?'], [0, 'Of books too dangerous to keep.'], [1, 'Where are the first ones?'], [0, 'Down. Where everything dangerous in Bellmourn goes.']] },
  { tags: ['learned', 'trio'], lines: [[0, 'Watch closely, both of you.'], [1, 'Is it going to explode?'], [2, "It's going to explode."], [0, 'It is not going to explode.'], [1, "It's smoking."], [2, "It's smoking a great deal."], [0, '...Lie down. Both of you. Now.']] },
  // -------------------------------------------------- husband and wife
  { tags: ['couple'], lines: [[0, 'Do you still love me, dear?'], [1, 'After thirty years?'], [0, 'Yes.'], [1, 'After thirty years, yes. Ask me again in thirty more.']] },
  { tags: ['couple'], lines: [[0, "You've been staring at the stranger, love."], [1, 'At their purse.'], [0, 'Truly?'], [1, 'Mostly.']] },
  { tags: ['couple'], lines: [[0, 'Come to bed, dear.'], [1, 'In a moment.'], [0, 'What are you doing?'], [1, 'Checking the shutters. Again.'], [0, "Check mine while you're at it. I'll warm the bed."]] },
  { tags: ['couple'], lines: [[0, "Your mother's coming to stay."], [1, 'From Millhaven?'], [0, "She says it isn't safe there."], [1, "It isn't safe here either."], [0, "Tell her. I tried. She's bringing her own lamp."]] },
  { tags: ['couple'], lines: [[0, "If the dead come, love, I'll protect you."], [1, 'With what?'], [0, 'With my body.'], [1, "Your body can't climb the stairs without a rest."], [0, "Then I'll protect the bottom of the stairs."]] },
  { tags: ['couple'], lines: [[0, 'You snore, dear.'], [1, "I don't snore."], [0, "You do. It's the only reason the dead don't come in."], [1, 'Why?'], [0, 'They think we keep a bear.']] },
  { tags: ['couple'], lines: [[0, "What shall we do when we're old, love?"], [1, 'We are old.'], [0, 'Older, then.'], [1, 'Sit by the fire and argue about which of us is older.']] },
  { tags: ['couple'], lines: [[0, 'I bought you a ribbon, love.'], [1, 'Green?'], [0, "Of course green. Everybody's wearing green."], [1, "Then I'll wear it under my collar, where only you'll see."]] },
  { tags: ['couple'], lines: [[0, 'We should have had children, dear.'], [1, 'In Bellmourn?'], [0, "Someone to mind the shop when we're gone."], [1, "The shop will mind itself. It's had the practice."]] },
  { tags: ['couple'], lines: [[0, "You've put the good spoons out."], [1, "The reeve's coming to supper."], [0, "He'll pocket one."], [1, "I've counted them."], [0, "He'll pocket the count."]] },
  { tags: ['couple'], lines: [[0, 'Do you remember our first dance?'], [1, 'In the square. Before the bell.'], [0, 'You trod on my foot.'], [1, 'You trod on mine first.'], [0, "We've been treading on each other ever since."], [1, "It's how I know where you are."]] },
  { tags: ['couple'], lines: [[0, 'I dreamt you went down the cathedral stair, love.'], [1, 'Me? Never.'], [0, 'After a copper that rolled away.'], [1, '...That does sound like me.']] },
  { tags: ['couple'], lines: [[0, 'Shall we give the stranger credit?'], [1, 'They might die.'], [0, 'They might not.'], [1, "Then they'll owe us double. Write it down in pencil, dear."]] },
  { tags: ['couple'], lines: [[0, 'Where were you all morning, love?'], [1, 'At the crater. Praying.'], [0, 'For what?'], [1, 'Customers. And you. In that order, this week.']] },
  { tags: ['couple'], lines: [[0, "I'm frightened, dear."], [1, 'Of the dead?'], [0, 'Of being the one left.'], [1, "Then we'll go together."], [0, 'Promise?'], [1, "I'll hold your hand the whole way down."]] },
  { tags: ['couple'], lines: [[0, 'The garrison was eyeing our stock again.'], [1, 'Let them eye it.'], [0, 'They were eyeing you as well.'], [1, 'Were they?'], [0, "Don't look so pleased."]] },
  { tags: ['couple'], lines: [[0, "You've been at the honey cakes."], [1, 'I have not.'], [0, 'There are crumbs on your chin, dear.'], [1, 'Those are from yesterday.'], [0, "That's worse."]] },
  { tags: ['couple'], lines: [[0, "Let's shut up early tonight, love."], [1, 'Why?'], [0, "I want to sit with you while it's still light."], [1, "It's nearly always dark."], [0, "Then let's sit with what's left of it."]] },
  { tags: ['couple'], lines: [[0, 'Will we go to heaven, do you think, dear?'], [1, 'With our prices?'], [0, "Heaven doesn't buy candles."], [1, "Then we'll set up a stall at the gate. Somebody has to."]] },
  { tags: ['couple'], lines: [[0, 'I married the cleverest trader in Bellmourn.'], [1, 'You did.'], [0, 'And the cleverest trader married me.'], [1, 'Best bargain I ever made.'], [0, "You'd sell me if the price were right."], [1, 'No price would be high enough. Nobody would pay it.']] },
  { tags: ['couple'], lines: [[0, "You're not to go out after dark, love."], [1, "Who'll fetch the water, then?"], [0, 'I will.'], [1, "Then you're not to go out after dark either."], [0, "Then we'll go thirsty together."]] },
  { tags: ['couple'], lines: [[0, "What's for supper, dear?"], [1, 'What there is.'], [0, 'And what is there?'], [1, 'Bread. And each other.'], [0, "I've had worse suppers."]] },
  { tags: ['couple'], lines: [[0, 'We should write a will, love.'], [1, 'Who gets the shop?'], [0, 'Whichever of us is left.'], [1, "That's grim."], [0, "It's practical. Put the stranger down as second."]] },
  { tags: ['couple'], lines: [[0, 'You kicked me in your sleep, dear.'], [1, 'I was running.'], [0, 'From what?'], [1, 'Toward you. In the dream you were faster than me, for once.']] },
  { tags: ['couple'], lines: [[0, 'The neighbours have moved out, love.'], [1, 'Fled?'], [0, 'To Millhaven.'], [1, "Millhaven's worse!"], [0, "They say they'd rather be killed by something they can see."]] },
  { tags: ['couple'], lines: [[0, "Let's spend some of the savings, dear."], [1, 'On what?'], [0, 'Something nice. Before the Sworn take it, or the dead do.'], [1, 'Like what?'], [0, 'A feather bed. Then at least the dead will find us comfortable.']] },
  { tags: ['couple'], lines: [[0, 'Have you still got the ring I gave you?'], [1, 'Always.'], [0, 'Even with gold so dear?'], [1, 'Even then. I had it valued, mind.'], [0, 'And?'], [1, 'You overpaid. I love you for it.']] },
  // ------------------------------------------ all sorts, three at once
  { tags: ['any', 'trio'], lines: [[0, 'Is it true, what they say of the stranger?'], [1, 'Which part?'], [2, 'The burning abbot?'], [0, "No. That they're fond of cheese."], [1, "That's true."], [2, "Then Bellmourn will be fine. We've cheese."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Do you hear that, the pair of you?'], [1, 'The bell?'], [2, 'Under the bell.'], [0, 'Lower than that.'], [1, 'Singing.'], [2, 'From under the cathedral floor.'], [0, "Let's go home and not hear it together."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Who wants to go and look at the crater?'], [1, 'Not me.'], [2, 'Not me.'], [0, "Nor me. Good. Let's all not go, together."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Settle something for us.'], [1, 'What?'], [0, 'Which is worse, the dead or the Sworn?'], [1, 'The dead.'], [2, 'The Sworn.'], [0, 'The one in the crater is both, now.'], [2, "Then he's the worst of all. And the least trouble."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Shall we pray together?'], [1, 'For what?'], [2, 'For the stranger.'], [0, 'For the stranger.'], [1, "And for us, while we're at it."], [2, "We're cheaper to pray for. Less to ask."]] },
  { tags: ['any', 'trio'], lines: [[0, 'There are a thousand dead under the cathedral.'], [1, 'Two thousand, I heard.'], [2, 'Three.'], [0, "It goes up every time it's told."], [1, 'Then stop telling it.'], [2, "Before it's all of us."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Three of us at the well. Just like when we were small.'], [1, 'You pushed me in, once.'], [2, 'You pushed me in twice.'], [0, 'And you both pulled me in after. I remember.'], [1, "Nobody's pushing anyone in now."], [2, "Not with what's at the bottom these days."]] },
  { tags: ['any', 'trio'], lines: [[0, "Who's walking me home?"], [1, "It's broad daylight."], [2, "It's barely noon."], [0, "The yard doesn't care what hour it is."], [1, "Fine. I'll take your left."], [2, "And I'll take your right, {a}. And nobody looks at the gate."]] },
  { tags: ['gossip', 'trio'], lines: [[0, "The reeve's ordered a new hat."], [1, 'Another one?'], [2, 'To keep the old one on.'], [0, 'A hat to hold a hat?'], [2, "Since the wind took his hair, he's taking no chances."]] },
  { tags: ['any', 'trio'], lines: [[0, 'Sing something, one of you.'], [1, 'What?'], [2, 'Not about the bell.'], [1, 'Not about the dead.'], [0, 'Not about the green star, with the garrison so near.'], [2, "Then there's nothing left but the one about the goat."], [1, 'Everyone knows the one about the goat.']] },
  { tags: ['any', 'trio'], lines: [[0, "If the stranger comes back from the deep, what'll you give them?"], [1, 'A pie.'], [2, 'A kiss.'], [0, 'A kiss!'], [2, "On the cheek. Through a cloth. They've been in the crypts."], [1, "I'll stick with the pie."]] },
];
